import React, { useState, useEffect } from 'react';
import { X, Gift, Calendar, Flame, Trophy } from 'lucide-react';
import { useSocial } from '../context/SocialContext';
import { useLanguage } from '../context/LanguageContext';
import { cn } from '../utils/cn';

export default function CheckInPanel({ onClose }) {
    const { checkIn, hasCheckedInToday, streakDays, points, getAchievements } = useSocial();
    const { language } = useLanguage();
    const [checkInResult, setCheckInResult] = useState(null);
    const [showAnimation, setShowAnimation] = useState(false);
    const [recentAchievements, setRecentAchievements] = useState([]);

    const hasChecked = hasCheckedInToday();

    // Get recently unlocked achievements
    useEffect(() => {
        const achievements = getAchievements().filter(a => a.unlocked);
        const today = new Date().toISOString().split('T')[0];
        const recent = achievements.filter(a =>
            a.unlockedAt && a.unlockedAt.startsWith(today)
        );
        setRecentAchievements(recent);
    }, [getAchievements]);

    const handleCheckIn = () => {
        const result = checkIn();
        setCheckInResult(result);
        if (result.success) {
            setShowAnimation(true);
            setTimeout(() => setShowAnimation(false), 2000);
        }
    };

    // Generate calendar for current week
    const getWeekDays = () => {
        const days = [];
        const today = new Date();
        const dayOfWeek = today.getDay();

        for (let i = 0; i < 7; i++) {
            const date = new Date(today);
            date.setDate(today.getDate() - dayOfWeek + i);
            const isToday = i === dayOfWeek;
            const isPast = i < dayOfWeek;

            days.push({
                day: ['鏃?, '涓€', '浜?, '涓?, '鍥?, '浜?, '鍏?][i],
                day_en: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][i],
                date: date.getDate(),
                isToday,
                isPast,
                checked: isPast || (isToday && hasChecked)
            });
        }
        return days;
    };

    const weekDays = getWeekDays();

    return (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={onClose}>
            <div
                className="bg-white rounded-xl w-full max-w-sm overflow-hidden animate-scale-in"
                onClick={e => e.stopPropagation()}
            >
                {/* Header */}
                <div className="relative overflow-hidden">
                    <div className="absolute inset-0 bg-gradient-to-r from-[var(--color-primary)] to-orange-400" />
                    {showAnimation && (
                        <div className="absolute inset-0 flex items-center justify-center">
                            <div className="text-6xl animate-bounce">馃帀</div>
                        </div>
                    )}
                    <div className="relative p-4 text-white">
                        <div className="flex items-center justify-between">
                            <h3 className="font-bold text-lg">
                                {language === 'zh' ? '姣忔棩绛惧埌' : 'Daily Check-in'}
                            </h3>
                            <button onClick={onClose} className="text-white/80 hover:text-white">
                                <X size={24} />
                            </button>
                        </div>

                        {/* Streak */}
                        <div className="flex items-center gap-2 mt-4">
                            <Flame className="text-yellow-300" size={24} />
                            <span className="text-xl font-bold">{streakDays}</span>
                            <span>{language === 'zh' ? '澶╄繛缁鍒? : 'day streak'}</span>
                        </div>

                        {/* Points */}
                        <div className="flex items-center gap-2 mt-2">
                            <Trophy className="text-yellow-300" size={20} />
                            <span>{language === 'zh' ? '鎬荤Н鍒? : 'Total Points'}:</span>
                            <span className="font-bold">{points}</span>
                        </div>
                    </div>
                </div>

                {/* Week Calendar */}
                <div className="p-4 bg-[var(--color-bg-app)]">
                    <div className="grid grid-cols-7 gap-2">
                        {weekDays.map((day, index) => (
                            <div key={index} className="text-center">
                                <p className="text-xs text-[var(--color-text-muted)] mb-1">
                                    {language === 'zh' ? day.day : day.day_en}
                                </p>
                                <div className={cn(
                                    "w-10 h-10 mx-auto rounded-full flex items-center justify-center text-sm font-medium transition-all",
                                    day.isToday && !day.checked && "ring-2 ring-[var(--color-primary)] ring-offset-2",
                                    day.checked
                                        ? "bg-[var(--color-primary)] text-white"
                                        : day.isPast
                                            ? "bg-gray-200 text-gray-400"
                                            : "bg-white text-[var(--color-text-main)]"
                                )}>
                                    {day.checked ? '鉁? : day.date}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Check In Result */}
                {checkInResult?.success && (
                    <div className="px-4 py-3 bg-green-50 text-green-700 text-center">
                        <p className="font-medium">
                            馃帀 {language === 'zh' ? '绛惧埌鎴愬姛!' : 'Check-in successful!'}
                        </p>
                        <p className="text-sm">
                            +{checkInResult.points} {language === 'zh' ? '绉垎' : 'points'}
                            {checkInResult.streak > 1 && (
                                <span className="ml-2">
                                    馃敟 {checkInResult.streak} {language === 'zh' ? '澶╄繛缁? : 'day streak'}
                                </span>
                            )}
                        </p>
                    </div>
                )}

                {/* Recent Achievements */}
                {recentAchievements.length > 0 && (
                    <div className="px-4 py-3 border-t border-[var(--color-border)]">
                        <p className="text-sm font-medium mb-2">
                            {language === 'zh' ? '馃弳 浠婃棩鎴愬氨' : '馃弳 Today\'s Achievements'}
                        </p>
                        {recentAchievements.map(a => (
                            <div key={a.id} className="text-sm text-[var(--color-primary)]">
                                鉁?{language === 'zh' ? a.name : a.name_en}
                            </div>
                        ))}
                    </div>
                )}

                {/* Check In Button */}
                <div className="p-4">
                    <button
                        onClick={handleCheckIn}
                        disabled={hasChecked}
                        className={cn(
                            "w-full py-3 rounded-lg font-medium transition-all flex items-center justify-center gap-2",
                            hasChecked
                                ? "bg-gray-200 text-gray-400 cursor-not-allowed"
                                : "bg-[var(--color-primary)] text-white hover:bg-[var(--color-primary-hover)]"
                        )}
                    >
                        <Calendar size={20} />
                        {hasChecked
                            ? (language === 'zh' ? '浠婃棩宸茬鍒? : 'Already checked in')
                            : (language === 'zh' ? '绔嬪嵆绛惧埌' : 'Check in now')
                        }
                    </button>
                </div>
            </div>
        </div>
    );
}

import React, { useRef, useState, useCallback } from 'react';
import { Upload, X, File, AlertCircle } from 'lucide-react';
import { useLanguage } from '../context/LanguageContext';
import { validateFile, processFileForChat } from '../utils/fileUtils';
import { cn } from '../utils/cn';

export default function FileUploader({ onFileSelect, onClose }) {
    const { t } = useLanguage();
    const fileInputRef = useRef(null);
    const [isDragging, setIsDragging] = useState(false);
    const [error, setError] = useState(null);
    const [isProcessing, setIsProcessing] = useState(false);

    const handleDragOver = useCallback((e) => {
        e.preventDefault();
        setIsDragging(true);
    }, []);

    const handleDragLeave = useCallback((e) => {
        e.preventDefault();
        setIsDragging(false);
    }, []);

    const handleDrop = useCallback(async (e) => {
        e.preventDefault();
        setIsDragging(false);
        setError(null);

        const files = Array.from(e.dataTransfer.files);
        if (files.length > 0) {
            await processFile(files[0]);
        }
    }, []);

    const handleFileSelect = useCallback(async (e) => {
        setError(null);
        const files = Array.from(e.target.files);
        if (files.length > 0) {
            await processFile(files[0]);
        }
    }, []);

    const processFile = async (file) => {
        setIsProcessing(true);
        try {
            const validation = validateFile(file);
            if (!validation.valid) {
                setError(t(validation.errors[0]));
                setIsProcessing(false);
                return;
            }

            const fileData = await processFileForChat(file);
            onFileSelect?.(fileData);
            onClose?.();
        } catch (err) {
            setError(t(err.message) || t('error'));
        } finally {
            setIsProcessing(false);
        }
    };

    return (
        <div className="absolute bottom-full mb-2 left-0 w-72 bg-white rounded-lg shadow-xl border border-gray-200 overflow-hidden z-50">
            {/* Header */}
            <div className="flex items-center justify-between px-3 py-2 border-b border-gray-100">
                <span className="font-medium text-sm text-gray-700">{t('upload_file')}</span>
                <button
                    onClick={onClose}
                    className="p-1 hover:bg-gray-100 rounded text-gray-500"
                >
                    <X size={16} />
                </button>
            </div>

            {/* Drop zone */}
            <div
                onDragOver={handleDragOver}
                onDragLeave={handleDragLeave}
                onDrop={handleDrop}
                onClick={() => fileInputRef.current?.click()}
                className={cn(
                    "m-3 p-6 border-2 border-dashed rounded-lg transition-colors cursor-pointer text-center",
                    isDragging
                        ? "border-[var(--color-primary)] bg-[var(--color-primary)]/5"
                        : "border-gray-200 hover:border-gray-300"
                )}
            >
                <input
                    ref={fileInputRef}
                    type="file"
                    onChange={handleFileSelect}
                    className="hidden"
                    accept=".txt,.md,.json,.js,.ts,.py,.html,.css,.xml,.csv,.yaml,.yml"
                />

                {isProcessing ? (
                    <div className="flex flex-col items-center gap-2">
                        <div className="w-8 h-8 border-2 border-[var(--color-primary)] border-t-transparent rounded-full animate-spin" />
                        <p className="text-sm text-gray-500">{t('uploading')}</p>
                    </div>
                ) : (
                    <>
                        <Upload className="w-8 h-8 mx-auto mb-2 text-gray-400" />
                        <p className="text-sm text-gray-600 mb-1">{t('drag_drop_file')}</p>
                        <p className="text-xs text-gray-400">{t('or_click_to_upload')}</p>
                    </>
                )}
            </div>

            {/* Error message */}
            {error && (
                <div className="mx-3 mb-3 p-2 bg-red-50 border border-red-200 rounded-lg flex items-center gap-2 text-red-600 text-sm">
                    <AlertCircle size={16} />
                    {error}
                </div>
            )}

            {/* Supported formats */}
            <div className="px-3 pb-3">
                <p className="text-xs text-gray-400 text-center">
                    {t('supported_formats')}
                </p>
            </div>
        </div>
    );
}

