import React, { useState, useEffect } from 'react';
import { X, RotateCcw } from 'lucide-react';
import { useLanguage } from '../../../context/LanguageContext';
import { cn } from '../../../utils/cn';

// Game choices
const CHOICES = [
    { id: 'rock', emoji: '鉁?, name: '鐭冲ご', name_en: 'Rock' },
    { id: 'paper', emoji: '鉁?, name: '甯?, name_en: 'Paper' },
    { id: 'scissors', emoji: '鉁岋笍', name: '鍓垁', name_en: 'Scissors' }
];

const OUTCOMES = {
    rock: { rock: 'draw', paper: 'lose', scissors: 'win' },
    paper: { rock: 'win', paper: 'draw', scissors: 'lose' },
    scissors: { rock: 'lose', paper: 'win', scissors: 'draw' }
};

export default function RockPaperScissors({ aiName, onClose, onResult }) {
    const { t, language } = useLanguage();
    const [playerChoice, setPlayerChoice] = useState(null);
    const [aiChoice, setAiChoice] = useState(null);
    const [result, setResult] = useState(null);
    const [countdown, setCountdown] = useState(null);
    const [score, setScore] = useState({ player: 0, ai: 0 });
    const [round, setRound] = useState(1);

    // AI makes its choice after player
    useEffect(() => {
        if (playerChoice && !aiChoice) {
            setCountdown(3);
        }
    }, [playerChoice, aiChoice]);

    // Countdown and reveal
    useEffect(() => {
        if (countdown === null) return;

        if (countdown > 0) {
            const timer = setTimeout(() => setCountdown(countdown - 1), 500);
            return () => clearTimeout(timer);
        } else {
            // AI picks randomly
            const randomChoice = CHOICES[Math.floor(Math.random() * CHOICES.length)];
            setAiChoice(randomChoice);

            // Determine result
            const outcome = OUTCOMES[playerChoice.id][randomChoice.id];
            setResult(outcome);

            // Update score
            if (outcome === 'win') {
                setScore(prev => ({ ...prev, player: prev.player + 1 }));
            } else if (outcome === 'lose') {
                setScore(prev => ({ ...prev, ai: prev.ai + 1 }));
            }
        }
    }, [countdown, playerChoice]);

    const handleChoice = (choice) => {
        if (playerChoice) return; // Already chose
        setPlayerChoice(choice);
    };

    const handlePlayAgain = () => {
        setPlayerChoice(null);
        setAiChoice(null);
        setResult(null);
        setCountdown(null);
        setRound(prev => prev + 1);
    };

    const handleFinish = () => {
        const finalResult = score.player > score.ai ? 'win' : score.player < score.ai ? 'lose' : 'draw';
        onResult?.({ result: finalResult, score, rounds: round });
        onClose?.();
    };

    const getResultMessage = () => {
        if (!result) return '';
        if (result === 'win') return language === 'zh' ? '浣犺耽浜? 馃帀' : 'You win! 馃帀';
        if (result === 'lose') return language === 'zh' ? `${aiName} 璧簡!` : `${aiName} wins!`;
        return language === 'zh' ? '骞冲眬!' : 'Draw!';
    };

    const getResultColor = () => {
        if (!result) return '';
        if (result === 'win') return 'text-green-500';
        if (result === 'lose') return 'text-red-500';
        return 'text-yellow-500';
    };

    return (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4" onClick={onClose}>
            <div
                className="bg-white rounded-xl w-full max-w-sm overflow-hidden animate-scale-in"
                onClick={e => e.stopPropagation()}
            >
                {/* Header */}
                <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--color-border)] bg-gradient-to-r from-[var(--color-primary)] to-[var(--color-primary-hover)]">
                    <h3 className="font-bold text-white text-lg">
                        {language === 'zh' ? '鉁?鐭冲ご鍓垁甯?鉁岋笍' : '鉁?Rock Paper Scissors 鉁岋笍'}
                    </h3>
                    <button onClick={onClose} className="text-white/80 hover:text-white">
                        <X size={24} />
                    </button>
                </div>

                {/* Score */}
                <div className="flex justify-between items-center px-6 py-3 bg-[var(--color-bg-app)]">
                    <div className="text-center">
                        <p className="text-sm text-[var(--color-text-muted)]">{t('you') || 'You'}</p>
                        <p className="text-2xl font-bold text-[var(--color-primary)]">{score.player}</p>
                    </div>
                    <div className="text-center">
                        <p className="text-sm text-[var(--color-text-muted)]">{language === 'zh' ? '绗? : 'Round'} {round} {language === 'zh' ? '杞? : ''}</p>
                        <p className="text-lg font-medium">VS</p>
                    </div>
                    <div className="text-center">
                        <p className="text-sm text-[var(--color-text-muted)]">{aiName}</p>
                        <p className="text-2xl font-bold text-red-500">{score.ai}</p>
                    </div>
                </div>

                {/* Game Area */}
                <div className="p-6">
                    {/* Choices Display */}
                    <div className="flex justify-center items-center gap-8 mb-6">
                        <div className="text-center">
                            <div className={cn(
                                "w-20 h-20 rounded-full bg-blue-100 flex items-center justify-center text-4xl transition-all",
                                playerChoice && "animate-bounce-once"
                            )}>
                                {playerChoice ? playerChoice.emoji : '鉂?}
                            </div>
                            <p className="mt-2 text-sm font-medium">{t('you') || 'You'}</p>
                        </div>

                        <div className="text-2xl font-bold text-[var(--color-text-muted)]">
                            {countdown !== null && countdown > 0 ? countdown : 'VS'}
                        </div>

                        <div className="text-center">
                            <div className={cn(
                                "w-20 h-20 rounded-full bg-red-100 flex items-center justify-center text-4xl transition-all",
                                aiChoice && "animate-bounce-once"
                            )}>
                                {aiChoice ? aiChoice.emoji : (countdown !== null ? '馃' : '鉂?)}
                            </div>
                            <p className="mt-2 text-sm font-medium">{aiName}</p>
                        </div>
                    </div>

                    {/* Result */}
                    {result && (
                        <div className={cn("text-center text-xl font-bold mb-4", getResultColor())}>
                            {getResultMessage()}
                        </div>
                    )}

                    {/* Choice Buttons */}
                    {!playerChoice && (
                        <div>
                            <p className="text-center text-sm text-[var(--color-text-muted)] mb-4">
                                {language === 'zh' ? '閫夋嫨浣犵殑鍑烘嫑' : 'Make your choice'}
                            </p>
                            <div className="flex justify-center gap-4">
                                {CHOICES.map(choice => (
                                    <button
                                        key={choice.id}
                                        onClick={() => handleChoice(choice)}
                                        className="w-16 h-16 rounded-full bg-[var(--color-bg-app)] hover:bg-[var(--color-primary)] hover:text-white text-3xl transition-all hover:scale-110 active:scale-95"
                                    >
                                        {choice.emoji}
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Play Again / Finish */}
                    {result && (
                        <div className="flex gap-3">
                            <button
                                onClick={handlePlayAgain}
                                className="flex-1 py-3 bg-[var(--color-primary)] text-white rounded-lg font-medium flex items-center justify-center gap-2 hover:bg-[var(--color-primary-hover)] transition-colors"
                            >
                                <RotateCcw size={18} />
                                {language === 'zh' ? '鍐嶆潵涓€灞€' : 'Play Again'}
                            </button>
                            <button
                                onClick={handleFinish}
                                className="flex-1 py-3 bg-[var(--color-bg-app)] text-[var(--color-text-main)] rounded-lg font-medium hover:bg-gray-200 transition-colors"
                            >
                                {language === 'zh' ? '缁撴潫' : 'Finish'}
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

import React, { useState, useRef } from 'react';
import {
    Smile, Paperclip, Mic, Send, MoreVertical, X,
    Image as ImageIcon, FileText, Gift, Heart,
    Gamepad2, BarChart3, Coins, Plus, Keyboard, MoreHorizontal
} from 'lucide-react';
import { useChat } from '../../context/ChatContext';
import { useLanguage } from '../../../../context/LanguageContext';
import { cn } from '../../../../utils/cn';
import EmojiPicker from '../../../../components/EmojiPicker';
import StickerPicker from '../../../../components/StickerPicker';
import FileUploader from '../../../../components/FileUploader';

// Menu Button Helper
const MenuButton = ({ icon: Icon, label, onClick, color = "text-gray-600", bg = "bg-gray-50" }) => (
    <button
        onClick={onClick}
        className="flex flex-col items-center gap-2 p-3 rounded-2xl hover:bg-gray-50 transition-colors group"
    >
        <div className={cn("w-12 h-12 rounded-2xl flex items-center justify-center transition-all group-hover:scale-110 shadow-sm", bg)}>
            <Icon size={24} className={color} />
        </div>
        <span className="text-xs font-medium text-gray-600">{label}</span>
    </button>
);

export default function ChatComposer({ chat, onSendMessage, onSendFile, onSendSticker, quotedMessage, onCancelQuote }) {
    const { t, language } = useLanguage();
    const { personas } = useChat();
    const [inputValue, setInputValue] = useState('');
    const [isRecording, setIsRecording] = useState(false);
    const [showEmojiPicker, setShowEmojiPicker] = useState(false);
    const [showStickerPicker, setShowStickerPicker] = useState(false);
    const [showFileUploader, setShowFileUploader] = useState(false);
    const [showPlusMenu, setShowPlusMenu] = useState(false);
    const inputRef = useRef(null);
    const [recordingStart, setRecordingStart] = useState(0);
    const [isRecordingMode, setIsRecordingMode] = useState(false);

    // Mention state
    const [showMentionDropdown, setShowMentionDropdown] = useState(false);
    const [mentionCandidates, setMentionCandidates] = useState([]);

    const headerInfo = (() => {
        if (!chat) return {};
        const isDM = chat.participants.length === 2;
        if (isDM) {
            const otherId = chat.participants.find(p => p !== 'user-me');
            const other = personas.find(p => p.id === otherId);
            return other || {};
        }
        return { name: chat.name, id: chat.id };
    })();

    // Close all popups
    const closeAll = () => {
        setShowEmojiPicker(false);
        setShowStickerPicker(false);
        setShowPlusMenu(false);
        setShowFileUploader(false);
    };

    const handleInputChange = (e) => {
        const val = e.target.value;
        setInputValue(val);

        // Detect mention trigger '@'
        const lastChar = val.slice(-1);
        if (lastChar === '@') {
            setShowMentionDropdown(true);
            setMentionQuery('');
            setMentionCandidates(
                chat.participants
                    .filter(pid => pid !== 'user-me')
                    .map(pid => personas.find(p => p.id === pid))
                    .filter(Boolean)
            );
        } else if (showMentionDropdown) {
            // Simple logic: if space, close. If typing, filter (simplified)
            if (lastChar === ' ') {
                setShowMentionDropdown(false);
            }
        }
    };

    const handleMentionSelect = (persona) => {
        setInputValue(prev => prev + (persona.name || 'User') + ' ');
        setShowMentionDropdown(false);
        inputRef.current?.focus();
    };

    const handleSend = (e) => {
        e.preventDefault();
        if (!inputValue.trim()) return;
        onSendMessage(inputValue);
        setInputValue('');
        closeAll();
    };

    const getSenderName = (senderId) => {
        if (senderId === 'user-me') return t('you');
        const p = personas.find(p => p.id === senderId);
        return p ? (p.name || 'AI') : 'Unknown';
    };

    const onFileSelect = (file) => {
        onSendFile(file);
        // Logic handled by parent or hook
    };

    const handleEmojiSelect = (emoji) => {
        setInputValue(prev => prev + emoji);
    };

    const handleStickerSelect = (stickerUrl) => {
        onSendSticker(stickerUrl);
        setShowStickerPicker(false);
    };

    // Features
    const onOpenGift = () => {
        alert(language === 'zh' ? '閫佺ぜ鐗╁姛鑳藉紑鍙戜腑...' : 'Gift feature coming soon...');
    };
    const onOpenRedPacket = () => {
        alert(language === 'zh' ? '绾㈠寘鍔熻兘寮€鍙戜腑...' : 'Red Packet feature coming soon...');
    };
    const onOpenGame = () => {
        alert(language === 'zh' ? '浜掑姩娓告垙寮€鍙戜腑...' : 'Game feature coming soon...');
    };
    const onOpenPoll = () => {
        alert(language === 'zh' ? '鎶曠エ鍔熻兘寮€鍙戜腑...' : 'Poll feature coming soon...');
    };

    return (
        <div className="flex flex-col relative z-20 pb-4 px-4">
            {/* Quoted Preview - Floating Pill */}
            {quotedMessage && (
                <div className="mx-2 mb-2 px-4 py-3 glass-crystal rounded-[var(--radius-lg)] shadow-floating 
                    flex items-center justify-between animate-fade-slide-up ring-1 ring-white/60">
                    <div className="flex items-center gap-3 flex-1 min-w-0">
                        <div className="w-1 h-10 rounded-full animate-aurora"
                            style={{ background: 'var(--gradient-aurora)' }} />
                        <div className="min-w-0">
                            <p className="text-xs font-bold text-[var(--color-primary)]">
                                {t('reply_to')} {getSenderName(quotedMessage.senderId)}
                            </p>
                            <p className="text-xs text-[var(--color-text-muted)] truncate mt-0.5 font-medium opacity-80">
                                {quotedMessage.content.slice(0, 50)}...
                            </p>
                        </div>
                    </div>
                    <button
                        onClick={onCancelQuote}
                        className="p-2 hover:bg-white/80 rounded-full text-[var(--color-text-muted)]
                            hover:text-[var(--color-danger)] transition-colors"
                    >
                        <X size={16} />
                    </button>
                </div>
            )}

            {/* Main Composer Area - Floating Crystal Pill box */}
            <div className="glass-crystal rounded-[var(--radius-xl)] shadow-floating p-2 ring-1 ring-white/60 relative">
                <form onSubmit={handleSend} className="flex items-end gap-2">
                    {/* Voice/Keyboard Toggle */}
                    <button
                        type="button"
                        className={cn(
                            "p-3 rounded-full transition-all duration-300 mb-0.5",
                            isRecordingMode
                                ? "text-[var(--color-primary)] bg-[var(--color-primary-softer)] shadow-inner"
                                : "text-[var(--color-text-muted)] hover:text-[var(--color-primary)] hover:bg-[var(--color-bg-hover)]"
                        )}
                        onClick={() => setIsRecordingMode(!isRecordingMode)}
                    >
                        {isRecordingMode ? <Keyboard size={24} /> : <Mic size={24} />}
                    </button>

                    {isRecordingMode ? (
                        <button
                            type="button"
                            onMouseDown={(e) => { e.preventDefault(); setIsRecording(true); setRecordingStart(Date.now()); }}
                            onMouseUp={(e) => {
                                e.preventDefault();
                                if (isRecording) {
                                    setIsRecording(false);
                                    const duration = Math.round((Date.now() - recordingStart) / 1000);
                                    if (duration >= 1) onSendMessage(`[VOICE:${duration}s]`);
                                }
                            }}
                            onMouseLeave={() => setIsRecording(false)}
                            className={cn(
                                "flex-1 rounded-[var(--radius-lg)] px-4 py-3 text-[15px] font-bold transition-all select-none text-center",
                                isRecording
                                    ? "text-white scale-[0.98] shadow-inner animate-aurora"
                                    : "bg-white/50 hover:bg-white/80 text-[var(--color-text-main)]"
                            )}
                            style={isRecording ? { background: 'var(--gradient-aurora)', backgroundSize: '150% 150%' } : {}}
                        >
                            {isRecording
                                ? (language === 'zh' ? '馃帣锔?鏉惧紑鍙戦€? : '馃帣锔?Release to Send')
                                : (language === 'zh' ? '鎸変綇璇磋瘽' : 'Hold to Talk')}
                        </button>
                    ) : (
                        <div className="flex-1 relative min-h-[48px] flex items-center bg-white/50 rounded-[var(--radius-lg)] transition-all hover:bg-white/70 focus-within:bg-white focus-within:shadow-sm ring-1 ring-transparent focus-within:ring-[var(--color-primary)]/20 px-4">
                            <input
                                ref={inputRef}
                                type="text"
                                value={inputValue}
                                onChange={handleInputChange}

                                placeholder={t('type_message')}
                                className="w-full bg-transparent border-none py-3 text-[16px] 
                                    text-[var(--color-text-main)] placeholder:text-[var(--color-text-muted)] 
                                    focus:outline-none font-medium"
                            />
                            {showMentionDropdown && mentionCandidates.length > 0 && (
                                <div className="absolute bottom-full left-0 mb-4 glass-crystal rounded-[var(--radius-lg)] 
                                    shadow-floating border border-white/40 py-2 min-w-[220px] max-h-[240px] 
                                    overflow-y-auto z-40 animate-scale-spring">
                                    {mentionCandidates.map(p => (
                                        <button
                                            key={p.id}
                                            onClick={() => handleMentionSelect(p)}
                                            className="w-full text-left px-4 py-3 hover:bg-[var(--color-bg-hover)]
                                                flex items-center gap-3 transition-all"
                                        >
                                            <div className="w-8 h-8 rounded-full overflow-hidden shadow-sm">
                                                {p.avatar
                                                    ? <img src={p.avatar} alt="" className="w-full h-full object-cover" />
                                                    : <div className="w-full h-full flex items-center justify-center text-white text-xs font-bold"
                                                        style={{ background: 'var(--gradient-aurora)' }}>{p.name.charAt(0)}</div>
                                                }
                                            </div>
                                            <span className="font-bold text-[var(--color-text-main)]">
                                                @{language === 'zh' ? (p.name_zh || p.name) : p.name}
                                            </span>
                                        </button>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}

                    {/* Action Buttons */}
                    <div className="flex items-center gap-1 mb-0.5">
                        <button
                            type="button"
                            className={cn(
                                "p-3 rounded-full transition-all duration-200",
                                showEmojiPicker
                                    ? "text-[var(--color-primary)] bg-[var(--color-primary-softer)]"
                                    : "text-[var(--color-text-muted)] hover:text-[var(--color-accent-gold)] hover:bg-white/60"
                            )}
                            onClick={() => { closeAll(); setShowEmojiPicker(!showEmojiPicker); }}
                        >
                            <Smile size={24} />
                        </button>

                        {inputValue.trim() ? (
                            <button
                                type="submit"
                                className="ml-1 p-3 rounded-full text-white shadow-lg
                                    hover:scale-105 active:scale-95
                                    transition-all duration-300 animate-aurora"
                                style={{ background: 'var(--gradient-aurora)', backgroundSize: '150% 150%' }}
                            >
                                <Send size={22} className="ml-0.5" />
                            </button>
                        ) : (
                            <button
                                type="button"
                                className={cn(
                                    "p-3 rounded-full transition-all duration-300",
                                    showPlusMenu
                                        ? "text-white rotate-45 shadow-md"
                                        : "text-[var(--color-text-muted)] hover:text-[var(--color-primary)] hover:bg-white/60"
                                )}
                                style={showPlusMenu ? { background: 'var(--gradient-aurora)' } : {}}
                                onClick={() => { closeAll(); setShowPlusMenu(!showPlusMenu); }}
                            >
                                <Plus size={24} />
                            </button>
                        )}
                    </div>
                </form>
            </div>

            {/* Popups - Premium Glass Stylings */}
            {showEmojiPicker && (
                <div className="absolute bottom-full left-4 mb-3 z-30 animate-scale-spring max-h-[400px]">
                    <EmojiPicker onSelect={handleEmojiSelect} onClose={() => setShowEmojiPicker(false)} />
                </div>
            )}
            {showStickerPicker && (
                <div className="absolute bottom-full left-4 mb-3 z-30 animate-scale-spring">
                    <StickerPicker aiId={headerInfo.id} onSelect={handleStickerSelect} onClose={() => setShowStickerPicker(false)} />
                </div>
            )}
            {showPlusMenu && (
                <div className="absolute bottom-full right-4 mb-3 glass-crystal rounded-[var(--radius-xl)] shadow-floating 
                    border border-white/40 p-4 min-w-[280px] grid grid-cols-4 gap-3 z-30 animate-scale-spring">
                    <MenuButton icon={Paperclip} label={t('file')} onClick={() => setShowFileUploader(true)}
                        color="text-[var(--color-accent-sky)]" bg="bg-sky-50" />
                    <MenuButton icon={Heart} label={language === 'zh' ? '璐寸焊' : 'Sticker'} onClick={() => setShowStickerPicker(true)}
                        color="text-[var(--color-accent-coral)]" bg="bg-pink-50" />
                    <MenuButton icon={Gift} label={language === 'zh' ? '绀肩墿' : 'Gift'} onClick={onOpenGift}
                        color="text-[var(--color-accent-coral)]" bg="bg-pink-50" />
                    <MenuButton icon={Coins} label={language === 'zh' ? '绾㈠寘' : 'Packet'} onClick={onOpenRedPacket}
                        color="text-red-500" bg="bg-red-50" />
                    <MenuButton icon={Gamepad2} label={language === 'zh' ? '娓告垙' : 'Game'} onClick={onOpenGame}
                        color="text-[var(--color-accent-lavender)]" bg="bg-purple-50" />
                    <MenuButton icon={BarChart3} label={language === 'zh' ? '鎶曠エ' : 'Poll'} onClick={onOpenPoll}
                        color="text-[var(--color-primary)]" bg="bg-orange-50" />
                </div>
            )}

            {showFileUploader && (
                <div className="absolute bottom-20 left-4 mb-2 z-40 animate-scale-spring">
                    <FileUploader
                        onFileSelect={(file) => { onFileSelect(file); setShowFileUploader(false); closeAll(); }}
                        onClose={() => setShowFileUploader(false)}
                    />
                </div>
            )}
        </div>
    );
}

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Search, MoreHorizontal, Sparkles, Image } from 'lucide-react';
import { useLanguage } from '../../../../context/LanguageContext';
import { cn } from '../../../../utils/cn';

export default function ChatHeader({ chat, personas, typingIndicators, onOpenBackground }) {
    const navigate = useNavigate();
    const { t, language } = useLanguage();

    const getHeaderInfo = () => {
        if (!chat) return { name: '', avatar: null, id: null };

        if (chat.participants.length === 2) {
            const otherId = chat.participants.find(p => p !== 'user-me');
            const other = personas.find(p => p.id === otherId);
            const name = language === 'zh' && other ? (other.name_zh || other.name) : (other?.name || chat.name);
            return { name: name, avatar: other?.avatar, id: otherId };
        }
        return {
            name: chat.name,
            avatar: null,
            memberCount: chat.participants.length,
            id: null
        };
    };

    const headerInfo = getHeaderInfo();

    // Get typing AI names
    const typingAIs = typingIndicators?.[chat.id] || [];
    const typingNames = typingAIs
        .map(aiId => {
            const ai = personas.find(p => p.id === aiId);
            return language === 'zh' ? (ai?.name_zh || ai?.name) : ai?.name;
        })
        .filter(Boolean);

    return (
        <div className="px-4 py-3 glass-strong flex items-center justify-between 
            border-b border-[var(--color-border-light)] sticky top-0 z-30 
            animate-fade-slide-down">
            {/* Aurora accent line */}
            <div className="absolute bottom-0 left-0 right-0 h-[1px] opacity-50"
                style={{ background: 'var(--gradient-aurora)' }} />

            <div className="flex items-center gap-3">
                {/* Back Button - Mobile */}
                <button
                    onClick={() => navigate('/')}
                    className="md:hidden p-2 -ml-2 rounded-xl hover:bg-[var(--color-bg-hover)] 
                        text-[var(--color-text-main)] transition-all duration-200 active:scale-95"
                >
                    <ArrowLeft size={22} />
                </button>

                {/* Avatar - Premium style */}
                {headerInfo.avatar && (
                    <div className="relative hidden md:block">
                        <div className="w-10 h-10 rounded-xl overflow-hidden shadow-sm 
                            ring-2 ring-white/80 transition-all duration-300 hover:shadow-md hover:scale-105">
                            <img
                                src={headerInfo.avatar}
                                alt={headerInfo.name}
                                className="w-full h-full object-cover"
                            />
                        </div>
                        {/* Online indicator */}
                        <div className="absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 
                            bg-[var(--color-success)] rounded-full border-2 border-white shadow-sm" />
                    </div>
                )}

                <div>
                    <h2
                        className="font-semibold text-[var(--color-text-main)] text-[17px] 
                            cursor-pointer flex items-center gap-2 hover:text-[var(--color-primary)] 
                            transition-colors group"
                        onClick={() => navigate(`/chat/${chat.id}/details`)}
                    >
                        <span className="group-hover:underline decoration-2 decoration-[var(--color-primary)]/30 underline-offset-2">
                            {headerInfo.name}
                        </span>
                        {headerInfo.memberCount && (
                            <span className="px-2.5 py-1 text-xs rounded-full font-medium
                                shadow-inner border border-[var(--color-border-light)]"
                                style={{ background: 'var(--gradient-aurora-soft)' }}>
                                {headerInfo.memberCount}
                            </span>
                        )}
                    </h2>
                    {typingNames.length > 0 ? (
                        <div className="text-xs text-[var(--color-primary)] font-medium 
                            flex items-center gap-1.5 animate-fade-in mt-0.5">
                            <span className="flex items-center gap-0.5">
                                <span className="typing-dot" style={{ width: '4px', height: '4px' }}></span>
                                <span className="typing-dot" style={{ width: '4px', height: '4px', animationDelay: '0.15s' }}></span>
                                <span className="typing-dot" style={{ width: '4px', height: '4px', animationDelay: '0.3s' }}></span>
                            </span>
                            <span>
                                {typingNames.length === 1
                                    ? `${typingNames[0]} ${t('is_typing')}`
                                    : `${typingNames.length} ${t('people_typing')}`
                                }
                            </span>
                        </div>
                    ) : (
                        <p className="text-xs text-[var(--color-text-muted)] flex items-center gap-1 mt-0.5">
                            <Sparkles size={12} className="text-[var(--color-accent-gold)]" />
                            {language === 'zh' ? 'AI 浼欎即鍦ㄧ嚎' : 'AI companion online'}
                        </p>
                    )}
                </div>
            </div>

            {/* Action Buttons */}
            <div className="flex items-center gap-1">
                <button
                    className="p-2.5 rounded-xl hover:bg-[var(--color-bg-hover)] 
