                </button>
            </div>
        </div>
    );
}

import React, { useRef, useEffect } from 'react';
import { cn } from '../../../../utils/cn';
import { formatTimeSeparator, shouldShowTimeSeparator } from '../../../../utils/formatTime';
import { downloadFile, formatFileSize } from '../../../../utils/fileUtils';
import { Paperclip, MoreHorizontal, Coins, Gamepad2 } from 'lucide-react';
import { useLanguage } from '../../../../context/LanguageContext';
import QuotedMessage from '../QuotedMessage';
import PollMessage from '../PollMessage';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { vscDarkPlus } from 'react-syntax-highlighter/dist/esm/styles/prism';
import { GeneratedFileMessage } from '../FileMessage';

export default function MessageTimeline({
    chat,
    currentUser,
    personas,
    onContextMenu,
    onVotePoll
}) {
    const { language } = useLanguage();
    const messagesEndRef = useRef(null);

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: "auto" });
    }, [chat?.messages]);

    const getSenderName = (senderId) => {
        if (senderId === 'user-me') return 'You'; // Simplified, trans handled in parent usually or hook
        const sender = personas.find(p => p.id === senderId);
        return language === 'zh' ? (sender?.name_zh || sender?.name) : sender?.name;
    };

    const getQuotedMessageData = (quotedId) => {
        if (!quotedId) return null;
        const msg = chat.messages.find(m => m.id === quotedId);
        if (!msg) return null;
        return {
            ...msg,
            senderName: getSenderName(msg.senderId)
        };
    };

    return (
        <div className="flex-1 overflow-y-auto p-3 pb-20 md:pb-4">
            {chat.messages.map((msg, index) => {
                const isMe = msg.senderId === 'user-me';
                const sender = isMe ? currentUser : personas.find(p => p.id === msg.senderId);
                const senderName = getSenderName(msg.senderId);

                let content = msg.content;
                let reaction = null;
                let type = 'text';
                let meta = null;

                // Parse custom message types (Legacy logic preserved)
                if (content.startsWith('[FILE]')) {
                    type = 'file';
                    content = content.replace('[FILE]', '').trim();
                } else if (content.startsWith('[STICKER:')) {
                    type = 'sticker';
                    const match = content.match(/\[STICKER:(.+?)\]/);
                    content = match ? match[1] : '';
                } else if (content.startsWith('[GIFT:')) {
                    type = 'gift';
                    const parts = content.match(/\[GIFT:(.+?):(.+?):(.+?)\]/);
                    if (parts) {
                        meta = { emoji: parts[1], name: parts[2], name_en: parts[3] };
                        content = language === 'zh' ? `閫佸嚭浜?${parts[2]}` : `Sent ${parts[3]}`;
                    }
                } else if (content.startsWith('[RED_PACKET:')) {
                    type = 'red_packet';
                    const parts = content.match(/\[RED_PACKET:(.+?):(.+?)\]/);
                    if (parts) {
                        meta = { amount: parts[1], message: parts[2] };
                        content = language === 'zh' ? '鏀跺埌绾㈠寘' : 'Red Packet';
                    }
                } else if (content.startsWith('[GAME:')) {
                    type = 'game';
                    content = content.replace('[GAME:', '').replace(']', '');
                } else if (content.startsWith('[POLL:')) {
                    type = 'poll';
                    const match = content.match(/\[POLL:(.+?)\]/);
                    if (match) {
                        const pollId = match[1];
                        const poll = chat.polls?.find(p => p.id === pollId);
                        if (poll) {
                            meta = { poll };
                        } else {
                            type = 'text';
                            content = '[Poll not found]';
                        }
                    }
                }

                const reactMatch = content.match(/\[REACT:(.+?)\]/);
                if (reactMatch) {
                    reaction = reactMatch[1];
                    content = content.replace(reactMatch[0], '').trim();
                }

                const prevMsg = index > 0 ? chat.messages[index - 1] : null;
                const showTimeSeparator = shouldShowTimeSeparator(prevMsg?.timestamp, msg.timestamp, 5);
                const quotedData = getQuotedMessageData(msg.quotedMessageId);

                return (
                    <React.Fragment key={msg.id}>
                        {showTimeSeparator && (
                            <div className="flex justify-center my-4">
                                <span className="px-3 py-1 bg-black/5 text-[var(--color-text-muted)] text-xs rounded-full">
                                    {formatTimeSeparator(msg.timestamp, language)}
                                </span>
                            </div>
                        )}

                        <div
                            className={cn("flex mb-4 animate-message-in group/msg", isMe ? "justify-end" : "justify-start")}
                            onContextMenu={(e) => onContextMenu(e, msg)}
                        >
                            <div className={cn("flex max-w-[75%] gap-2.5 min-w-0", isMe ? "flex-row-reverse" : "flex-row")}>
                                {/* Avatar */}
                                <div className="w-9 h-9 rounded-xl overflow-hidden flex-shrink-0 shadow-sm opacity-90 hover:opacity-100 transition-opacity">
                                    {sender?.avatar ? (
                                        <img src={sender.avatar} className="w-full h-full object-cover" alt="" />
                                    ) : (
                                        <div className="w-full h-full bg-gradient-to-br from-[var(--color-primary)] to-[var(--color-primary-active)] flex items-center justify-center text-white text-xs font-bold">
                                            {senderName?.charAt(0)}
                                        </div>
                                    )}
                                </div>

                                {/* Bubble */}
                                <div className="relative min-w-0 overflow-hidden">
                                    <div className={cn(
                                        "relative shadow-sm transition-all duration-200",
                                        (type === 'text' || type === 'file')
                                            ? (isMe
                                                ? "px-4 py-2.5 bg-gradient-to-br from-[var(--color-primary)] to-[var(--color-primary-active)] text-white rounded-2xl rounded-tr-sm"
                                                : "px-4 py-2.5 bg-white text-[var(--color-text-main)] rounded-2xl rounded-tl-sm border border-[var(--color-border-light)]")
                                            : "bg-transparent"
                                    )}>
                                        {quotedData && (
                                            <QuotedMessage quotedMessage={quotedData} senderName={quotedData.senderName} />
                                        )}

                                        {type === 'sticker' ? (
                                            <div className="text-7xl drop-shadow-md hover:scale-110 transition-transform cursor-pointer origin-bottom">
                                                {content}
                                            </div>
                                        ) : type === 'gift' && meta ? (
                                            <div className="bg-gradient-to-r from-pink-500 to-rose-500 text-white p-3 rounded-2xl shadow-lg flex items-center gap-3 min-w-[160px]">
                                                <div className="text-3xl bg-white/20 p-2 rounded-xl">{meta.emoji}</div>
                                                <div>
                                                    <p className="font-bold text-sm">{language === 'zh' ? meta.name : meta.name_en}</p>
                                                    <p className="text-xs opacity-90">{language === 'zh' ? '璧犻€佺ぜ鐗? : 'Gift Sent'}</p>
                                                </div>
                                            </div>
                                        ) : type === 'red_packet' && meta ? (
                                            <div className="bg-gradient-to-r from-[#FA9D3B] to-[#F76B1C] text-white p-1 rounded-2xl shadow-md cursor-pointer hover:shadow-lg transition-shadow min-w-[220px]">
                                                <div className="flex items-center gap-3 p-3">
                                                    <div className="bg-[#FEF2DC] rounded-xl p-2.5 text-[#FA9D3B]">
                                                        <Coins size={24} />
                                                    </div>
                                                    <div>
                                                        <p className="font-bold">{meta.message || (language === 'zh' ? '鎭枩鍙戣储' : 'Best Wishes')}</p>
                                                        <p className="text-xs opacity-90">{language === 'zh' ? '鏌ョ湅绾㈠寘' : 'Open Packet'}</p>
                                                    </div>
                                                </div>
                                                <div className="bg-white/10 px-3 py-1 rounded-b-xl text-[10px] opacity-80">
                                                    Chat Buddy Red Packet
                                                </div>
                                            </div>
                                        ) : type === 'game' ? (
                                            <div className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex flex-col items-center gap-2">
                                                <Gamepad2 size={24} className="text-[var(--color-primary)]" />
                                                <p className="font-medium text-center text-sm">{content}</p>
                                            </div>
                                        ) : type === 'poll' && meta?.poll ? (
                                            <div className="bg-white rounded-2xl overflow-hidden shadow-sm border border-gray-100 p-1">
                                                <PollMessage
                                                    poll={meta.poll}
                                                    onVote={(pollId, optionId) => onVotePoll(pollId, optionId)}
                                                />
                                            </div>
                                        ) : type === 'file' ? (
                                            <div className="flex items-center gap-3">
                                                <div className={cn("p-2 rounded-lg", isMe ? "bg-white/20" : "bg-gray-100")}>
                                                    <Paperclip size={20} className={isMe ? "text-white" : "text-[var(--color-text-muted)]"} />
                                                </div>
                                                <div className="text-sm underline underline-offset-2 opacity-90 hover:opacity-100 cursor-pointer">
                                                    {content}
                                                </div>
                                            </div>
                                        ) : (
                                            <div className="markdown-body prose prose-sm max-w-full break-words leading-relaxed text-inherit overflow-x-auto">
                                                <ReactMarkdown
                                                    remarkPlugins={[remarkGfm]}
                                                    components={{
                                                        // Custom components can be added here
                                                        a: ({ node, ...props }) => <a {...props} className="text-blue-500 hover:underline" target="_blank" rel="noopener noreferrer" />,
                                                        code: ({ node, inline, className, children, ...props }) => {
                                                            const match = /language-(\w+)/.exec(className || '');
                                                            return !inline && match ? (
                                                                <SyntaxHighlighter
                                                                    style={vscDarkPlus}
                                                                    language={match[1]}
                                                                    PreTag="div"
                                                                    className="rounded-md !bg-black/80 !p-3 !my-2 shadow-sm border border-white/10"
                                                                    {...props}
                                                                >
                                                                    {String(children).replace(/\n$/, '')}
                                                                </SyntaxHighlighter>
                                                            ) : (
                                                                <code className="bg-black/5 rounded px-1 py-0.5 text-[0.9em] font-mono" {...props}>
                                                                    {children}
                                                                </code>
                                                            );
                                                        },
                                                        table: ({ node, ...props }) => (
                                                            <div className="overflow-x-auto my-4 border border-gray-200 rounded-lg shadow-sm">
                                                                <table className="min-w-full divide-y divide-gray-200" {...props} />
                                                            </div>
                                                        ),
                                                        th: ({ node, ...props }) => <th className="px-3 py-2 bg-gray-50 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider" {...props} />,
                                                        td: ({ node, ...props }) => <td className="px-3 py-2 whitespace-nowrap text-sm text-gray-700 border-t border-gray-100" {...props} />
                                                    }}
                                                >
                                                    {content}
                                                </ReactMarkdown>
                                            </div>
                                        )}

                                        {reaction && (
                                            <span className="absolute -bottom-2 -right-2 bg-white rounded-full p-0.5 shadow-sm text-xs border border-gray-100 z-10 scale-110">
                                                {reaction}
                                            </span>
                                        )}
                                    </div>

                                    {/* Generated Files */}
                                    {msg.generatedFiles?.map((file, idx) => (
                                        <div key={idx} className="mt-2">
                                            <GeneratedFileMessage
                                                fileData={file}
                                                onDownload={() => downloadFile(file.filename, file.content)}
                                            />
                                        </div>
                                    ))}
                                </div>

                                <button
                                    onClick={(e) => onContextMenu(e, msg)}
                                    className={cn(
                                        "opacity-0 group-hover/msg:opacity-100 transition-opacity p-1.5 rounded-full hover:bg-gray-100 text-gray-400 self-center",
                                        isMe ? "mr-1" : "ml-1"
                                    )}
                                >
                                    <MoreHorizontal size={14} />
                                </button>
                            </div>
                        </div>
                    </React.Fragment>
                );
            })}
            <div ref={messagesEndRef} />
        </div>
    );
}

import React, { createContext, useContext, useCallback } from 'react';
import { useLocalStorage } from '../../../hooks/useLocalStorage';

const ChatActionContext = createContext();

// eslint-disable-next-line react-refresh/only-export-components
export const useChatActions = () => {
    const context = useContext(ChatActionContext);
    if (!context) throw new Error('useChatActions must be used within a ChatProvider');
    return context;
};

export const ChatActionProvider = ({ children, chatsRef, setChats, scheduledMessagesRef }) => {

    // Logic: Send Message
    const sendMessage = useCallback((chatId, content, senderId = 'user-me') => {
        // Cancel any scheduled proactive messages when user sends a message
        if (scheduledMessagesRef.current) {
            scheduledMessagesRef.current.forEach((timeoutId, key) => {
                if (key.startsWith(chatId)) {
                    clearTimeout(timeoutId);
                    scheduledMessagesRef.current.delete(key);
                }
            });
        }

        setChats(prevChats => prevChats.map(chat => {
            if (chat.id !== chatId) return chat;

            const newMessage = {
                id: crypto.randomUUID(),
                senderId,
                content,
                timestamp: new Date().toISOString(),
                status: 'sent'
            };

            return {
                ...chat,
                messages: [...chat.messages, newMessage],
                lastMessage: newMessage
            };
        }));
    }, [setChats, scheduledMessagesRef]);

    // Logic: Create Chat
    const createChat = useCallback((name, selectedPersonaIds) => {
        const newChat = {
            id: crypto.randomUUID(),
            name,
            participants: ['user-me', ...selectedPersonaIds],
            messages: [],
            createdAt: new Date().toISOString()
        };
        setChats(prev => [newChat, ...prev]);
        return newChat.id;
    }, [setChats]);

    // Logic: Update Chat
    const updateChat = useCallback((chatId, updates) => {
        setChats(prev => prev.map(chat =>
            chat.id === chatId ? { ...chat, ...updates } : chat
        ));
    }, [setChats]);

    // Logic: Delete Chat
    const deleteChat = useCallback((id) => {
        // Clear scheduled messages for this chat
        if (scheduledMessagesRef.current) {
            scheduledMessagesRef.current.forEach((timeoutId, key) => {
                if (key.startsWith(id)) {
                    clearTimeout(timeoutId);
                    scheduledMessagesRef.current.delete(key);
                }
            });
        }
        setChats(prev => prev.filter(c => c.id !== id));
    }, [setChats, scheduledMessagesRef]);

    // Logic: Delete/Recall Message
    const deleteMessage = useCallback((chatId, messageId) => {
        setChats(prev => prev.map(chat => {
            if (chat.id !== chatId) return chat;
            const updatedMessages = chat.messages.filter(m => m.id !== messageId);
            return {
                ...chat,
                messages: updatedMessages,
                lastMessage: updatedMessages[updatedMessages.length - 1] || null
            };
        }));
    }, [setChats]);

    // Logic: Clear Chat History
    const clearChatMessages = useCallback((chatId) => {
        setChats(prev => prev.map(chat => {
            if (chat.id !== chatId) return chat;
            return {
                ...chat,
                messages: [],
                lastMessage: null,
                pinnedMessages: []
            };
        }));
    }, [setChats]);

    // Logic: Pin/Unpin Chat
    const pinChat = useCallback((chatId, isPinned) => {
        setChats(prev => prev.map(chat =>
            chat.id === chatId ? { ...chat, isPinned } : chat
        ));
    }, [setChats]);

    // Logic: Mark Chat as Unread
    const markChatUnread = useCallback((chatId, isUnread = true) => {
        setChats(prev => prev.map(chat =>
            chat.id === chatId ? { ...chat, isUnread } : chat
        ));
    }, [setChats]);

    // Logic: Set Chat Category
    const setChatCategory = useCallback((chatId, category) => {
        setChats(prev => prev.map(chat =>
            chat.id === chatId ? { ...chat, category } : chat
        ));
    }, [setChats]);

    // Logic: Pin/Unpin Message
    const pinMessage = useCallback((chatId, messageId, isPinned = true) => {
        setChats(prev => prev.map(chat => {
            if (chat.id !== chatId) return chat;
            const pinnedMessages = chat.pinnedMessages || [];
            if (isPinned && !pinnedMessages.includes(messageId)) {
                return { ...chat, pinnedMessages: [...pinnedMessages, messageId] };
            } else if (!isPinned) {
                return { ...chat, pinnedMessages: pinnedMessages.filter(id => id !== messageId) };
            }
            return chat;
        }));
    }, [setChats]);

    // Logic: Vote on Poll
    const votePoll = useCallback((chatId, pollId, optionId) => {
        setChats(prev => prev.map(chat => {
            if (chat.id !== chatId) return chat;
            const polls = chat.polls || [];
            const pollIndex = polls.findIndex(p => p.id === pollId);
            if (pollIndex === -1) return chat;

            const poll = { ...polls[pollIndex] };
            const userId = 'user-me';

            if (poll.isMultiChoice) {
                const newOptions = poll.options.map(opt => {
                    if (opt.id === optionId) {
                        const votes = opt.votes || [];
                        if (votes.includes(userId)) {
                            return { ...opt, votes: votes.filter(id => id !== userId) };
                        } else {
                            return { ...opt, votes: [...votes, userId] };
                        }
                    }
                    return opt;
                });
                poll.options = newOptions;

            } else {
                const newOptions = poll.options.map(opt => {
                    const votes = opt.votes || [];
                    if (opt.id === optionId) {
                        if (!votes.includes(userId)) {
                            return { ...opt, votes: [...votes, userId] };
                        }
                        return opt;
                    } else {
                        return { ...opt, votes: votes.filter(id => id !== userId) };
                    }
                });
                poll.options = newOptions;
            }

            const newPolls = [...polls];
            newPolls[pollIndex] = poll;
            return { ...chat, polls: newPolls };
        }));
    }, [setChats]);

    const value = {
        sendMessage,
        createChat,
        updateChat,
        deleteChat,
        deleteMessage,
        clearChatMessages,
        pinChat,
        markChatUnread,
        setChatCategory,
        pinMessage,
        votePoll
    };

    return (
        <ChatActionContext.Provider value={value}>
            {children}
        </ChatActionContext.Provider>
    );
};

import { useState, useEffect } from 'react';
import { chatEngine } from '../../../core/chat/ChatEngine';
import { INITIAL_PERSONAS, getAllPersonas } from '../../../data/personas';

/**
 * Application Layer: Chat Service Hook
 * Connects the React View to the Domain ChatEngine.
 * 
 * Responsibilities:
 * - Initialize Engine
 * - Subscribe to Engine updates
 * - Expose Engine methods
 */
export function useChatService() {
    const [state, setState] = useState({
        chats: [],
        typingIndicators: {}
    });

    // Use ALL personas for the full list
    const allPersonas = getAllPersonas();

    useEffect(() => {
        // Initialize engine with ALL personas (includes Task Agents)
        chatEngine.init(allPersonas);

        // Subscribe to updates
        const unsubscribe = chatEngine.subscribe((newState) => {
            setState(newState);
        });

        return () => unsubscribe();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []); // Only run once on mount

    return {
        chats: state.chats,
        typingIndicators: state.typingIndicators,
        personas: allPersonas, // Includes ALL personas
        currentUser: { id: 'user-me', name: 'You', avatar: null },

        // Actions
        sendMessage: (chatId, content, quotedId) => chatEngine.sendMessage(chatId, content, 'user-me', quotedId),
        deleteMessage: (chatId, msgId) => chatEngine.deleteMessage(chatId, msgId),
        createChat: (name, pIds, avatar) => chatEngine.createChat(name, pIds, avatar),

        // Legacy Parity
        setChats: (newValue) => console.warn('setChats deprecated'),
        updateChat: (chatId, updates) => chatEngine.updateChat(chatId, updates),
        pinMessage: (chatId, msgId, isPinned) => chatEngine.pinMessage(chatId, msgId, isPinned),
        votePoll: (chatId, pollId, optionId) => chatEngine.votePoll(chatId, pollId, optionId),

        engine: chatEngine
    };
}

/**
 * Tool Service - Handles execution of AI tool calls
