/**
 * Execute fact-checking on a claim
 * @param {string} claim - The claim to verify
 * @returns {Promise<string>} Fact-check verdict with sources
 */
async function executeFactCheck(claim) {
    if (!claim) {
        return "[Fact Check Error] 璇锋彁渚涢渶瑕侀獙璇佺殑澹版槑銆俓

${claim}"`);

        const result = await factCheck(claim);

        // Map verdict to emoji and Chinese
        const verdictMap = {
            verified: { emoji: '鉁?, text: '宸查獙璇?(Verified)', color: 'green' },
            disputed: { emoji: '鈿狅笍', text: '瀛樺湪浜夎 (Disputed)', color: 'yellow' },
            unverifiable: { emoji: '鉂?, text: '鏃犳硶楠岃瘉 (Unverifiable)', color: 'gray' }
        };

        const confidenceMap = {
            high: '馃數 楂樼疆淇″害',
            medium: '馃煛 涓疆淇″害',
            low: '馃敶 浣庣疆淇″害'
        };

        const v = verdictMap[result.verdict] || verdictMap.unverifiable;
        const c = confidenceMap[result.confidence] || confidenceMap.low;

        let output = `馃敩 **浜嬪疄鏍告煡缁撴灉** | Claim: "${claim}"

---

## 鍒ゅ畾缁撴灉
${v.emoji} **${v.text}**
${c}

