export const useMomentsState = () => {
    const context = useContext(MomentsStateContext);
    if (!context) throw new Error('useMomentsState must be used within a MomentsProvider');
    return context;
};

export const MomentsStateProvider = ({ children }) => {
    const [momentsData, setMomentsData] = useLocalStorage('chat-buddy-moments', DEFAULT_MOMENTS_DATA);

    // Refs for intervals (moved here or staying in provider? If logic is extracted, refs might be needed in the logic hook)
    // Actually, the main provider (Facade) will hold the AI logic which uses these refs.
    // But the refs themselves are not really "State" that consumers need.
    // Consumers just need `posts` etc.

    // We will expose setters here so ActionProvider can use them.

    const value = {
        momentsData,
        setMomentsData,
        posts: momentsData.posts || [],
        lastAIPostTime: momentsData.lastAIPostTime || {},
        imageApiKey: momentsData.imageApiKey,
        imageApiUrl: momentsData.imageApiUrl
    };

    return (
        <MomentsStateContext.Provider value={value}>
            {children}
        </MomentsStateContext.Provider>
    );
};

import { useState, useEffect } from 'react';

export function useLocalStorage(key, initialValue) {
    // Get from local storage then use state
    const [storedValue, setStoredValue] = useState(() => {
        try {
            const item = window.localStorage.getItem(key);
            return item ? JSON.parse(item) : initialValue;
        } catch (error) {
            console.error(error);
            return initialValue;
        }
    });

    // Return a wrapped version of useState's setter function that ...
    // ... persists the new value to localStorage.
    const setValue = (value) => {
        try {
            // Allow value to be a function so we have same API as useState
            setStoredValue(current => {
                const valueToStore = value instanceof Function ? value(current) : value;
                // Save to local storage
                window.localStorage.setItem(key, JSON.stringify(valueToStore));
                return valueToStore;
            });
        } catch (error) {
            console.error(error);
        }
    };

    return [storedValue, setValue];
}

import React, { useState, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, MessageSquare, Plus, Clock, Search } from 'lucide-react';
import { useChat } from '../features/chat/context/ChatContext';
import { useLanguage } from '../context/LanguageContext';
import { cn } from '../utils/cn';
import ChatWindow from '../features/chat/ChatWindow';
import { formatChatListTime } from '../utils/formatTime';

export default function AgentWorkspace() {
    const { agentId } = useParams();
    const navigate = useNavigate();
    const { chats, createChat, personas } = useChat();
    const { t, language } = useLanguage();

    const [selectedChatId, setSelectedChatId] = useState(null);
    const [searchTerm, setSearchTerm] = useState('');

    // Find agent details
    const agent = personas.find(p => p.id === agentId);

    // Filter chats for this agent
    const agentChats = useMemo(() => {
        if (!agentId) return [];
        return chats
            .filter(chat => chat.participants.includes(agentId))
            .sort((a, b) => {
                const aTime = a.lastMessage?.timestamp || a.createdAt;
                const bTime = b.lastMessage?.timestamp || b.createdAt;
                return new Date(bTime) - new Date(aTime);
            });
    }, [chats, agentId]);

    // Handle creating a new chat
    const handleNewChat = () => {
        if (!agent) return;
        // Always create a new chat for "topics" in this workspace
        // Use a generic name or "New Chat" which will be updated by first message logic usually,
        // or we can prompt for a topic? For now, simple "Topic X" style or just "New Chat".
        // Let's verify createChat signature: createChat(name, participants, avatar)
        // If we want multiple chats, we must ensure distinctness or just rely on IDs.
        // The implementation says "Create new chat if none exists" in AgentsPage,
        // but createChat itself likely generates a unique ID.
        const chatName = language === 'zh' ? '鏂拌瘽棰? : 'New Topic';
        const newId = createChat(chatName, [agentId], agent.avatar);
        setSelectedChatId(newId);
    };

    if (!agent) {
        return <div className="flex items-center justify-center h-full text-gray-500">Agent not found</div>;
    }

    const displayName = language === 'zh' ? (agent.name_zh || agent.name) : agent.name;
    const activeChat = selectedChatId ? chats.find(c => c.id === selectedChatId) : null;

    return (
        <div className="flex h-full w-full bg-[var(--color-bg-app)]">
            {/* Left Sidebar - Chat List for this Agent */}
            <div className={cn(
                "flex flex-col border-r border-[var(--color-border)] bg-white transition-all duration-300",
                selectedChatId ? "hidden md:flex w-[320px]" : "w-full md:w-[320px]"
            )}>
                {/* Header */}
                <div className="p-4 border-b border-[var(--color-border-light)] bg-gray-50/50">
                    <div className="flex items-center gap-3 mb-4">
                        <button onClick={() => navigate('/agents')} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
                            <ArrowLeft size={20} />
                        </button>
                        <div className="flex-1 min-w-0">
                            <h1 className="font-bold text-lg truncate flex items-center gap-2">
                                <span className={cn("w-2 h-2 rounded-full", agent.color?.split(' ')[0] || 'bg-gray-400')}></span>
                                {displayName}
                            </h1>
                            <p className="text-xs text-gray-500 truncate">{language === 'zh' ? '涓撳睘宸ヤ綔鍖? : 'Workspace'}</p>
                        </div>
                    </div>

                    <button
                        onClick={handleNewChat}
                        className="w-full py-2.5 bg-[var(--color-primary)] hover:bg-[var(--color-primary-hover)] text-white rounded-xl font-medium flex items-center justify-center gap-2 transition-all shadow-sm active:scale-95"
                    >
                        <Plus size={18} />
                        {language === 'zh' ? '鏂板缓璇濋' : 'New Topic'}
                    </button>
                </div>

                {/* List */}
                <div className="flex-1 overflow-y-auto p-2 space-y-2">
                    {agentChats.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-10 text-gray-400 text-sm p-4 text-center">
                            <MessageSquare size={32} className="mb-2 opacity-20" />
                            <p>{language === 'zh' ? '杩樻病鏈夊璇濊褰? : 'No conversations yet'}</p>
                            <p className="text-xs mt-1">{language === 'zh' ? '鐐瑰嚮涓婃柟鎸夐挳寮€濮嬫柊璇濋' : 'Click above to start a topic'}</p>
                        </div>
                    ) : (
                        agentChats.map(chat => {
                            const lastMsg = chat.lastMessage;
                            const time = lastMsg ? formatChatListTime(lastMsg.timestamp, language) : '';
                            const isActive = chat.id === selectedChatId;

                            return (
                                <div
                                    key={chat.id}
                                    onClick={() => setSelectedChatId(chat.id)}
                                    className={cn(
                                        "p-3 rounded-xl cursor-pointer transition-all border border-transparent",
                                        isActive
                                            ? "bg-[var(--color-primary-softer)] border-[var(--color-primary-light)]"
                                            : "hover:bg-gray-50 hover:border-gray-200"
                                    )}
                                >
                                    <div className="flex justify-between items-start mb-1">
                                        <h3 className={cn("font-medium text-sm truncate pr-2 flex-1", isActive ? "text-[var(--color-primary-dark)]" : "text-gray-700")}>
                                            {chat.name || displayName}
                                        </h3>
                                        <span className="text-[10px] text-gray-400 whitespace-nowrap pt-0.5">{time}</span>
                                    </div>
                                    <p className="text-xs text-gray-500 line-clamp-2 min-h-[1.5em]">
                                        {lastMsg ? lastMsg.content : (language === 'zh' ? '(绌哄璇?' : '(Empty)')}
                                    </p>
                                </div>
                            );
                        })
                    )}
                </div>
            </div>

            {/* Right Side - Chat Window */}
            {selectedChatId ? (
                <div className={cn(
                    "flex-1 bg-[var(--color-bg-chat)] relative flex flex-col h-full",
                    selectedChatId ? "flex" : "hidden md:flex"
                )}>
                    {/* Mobile Back Button Overlay (if needed in header, but header handles navigation to root usually)
                        We need to override ChatHeader's back behavior or handle it via layout?
                        ChatWindow currently renders ChatHeader.
                        We might need to wrap ChatWindow or modify ChatHeader to handle "Back to Workspace List" on mobile.
                    */}
                    <div className="relative flex-1 flex flex-col min-h-0">
                        {/* We pass a key to force re-mount when switching chats if needed, though ID prop handling should suffice */}
                        <ChatWindow key={selectedChatId} chatId={selectedChatId} />

                        {/* Mobile Back Button Override: 
                            ChatWindow's header has a "md:hidden" back button that goes to '/'. 
                            We can't easily override it without modifying ChatHeader again.
                            However, on mobile, if we are in this view, we want to go back to the LIST of this workspace.
                            
                            Quick fix: We can overlay a back button or modify ChatHeader prop.
                            Let's assume for now user on mobile uses the header back button which goes to Home.
                            This is sub-optimal for "Workspace".
                            Ideally ChatHeader should accept an onBack prop.
                            For now, let's stick to desktop focus based on user persona, but if mobile, 
                            hitting "Back" (Browser) is standard.
                        */}
                    </div>
                </div>
            ) : (
                <div className="hidden md:flex flex-1 items-center justify-center bg-gray-50 text-gray-400 flex-col gap-4">
                    <div className={cn("w-20 h-20 rounded-3xl flex items-center justify-center shadow-sm", agent.color?.split(' ')[0] || 'bg-gray-200')}>
                        <img src={agent.avatar} alt="Agent" className="w-16 h-16 object-contain opacity-80" />
                    </div>
                    <p>{language === 'zh' ? '閫夋嫨涓€涓瘽棰樺紑濮? : 'Select a topic to start'}</p>
                </div>
            )}
        </div>
    );
}

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Bot, Search, MessageSquare, Sparkles } from 'lucide-react';
import { useChat } from '../features/chat/context/ChatContext';
import { useLanguage } from '../context/LanguageContext';
import { cn } from '../utils/cn';
import { getTaskSpecialists } from '../data/personas';

export default function AgentsPage() {
    const navigate = useNavigate();
    const { chats, createChat } = useChat();
    const { t, language } = useLanguage();
    const [searchTerm, setSearchTerm] = useState('');

    // Fetch only Task Specialist Agents
    const taskAgents = getTaskSpecialists();

    const filteredAgents = taskAgents.filter(agent => {
        const name = language === 'zh' ? (agent.name_zh || agent.name) : agent.name;
        const desc = language === 'zh' ? (agent.personality_zh || agent.personality) : agent.personality;
        const searchLower = searchTerm.toLowerCase();
        return name.toLowerCase().includes(searchLower) || desc.toLowerCase().includes(searchLower);
    });

    const handleChat = (agentId) => {
        // Navigate to the agent's dedicated workspace
        navigate(`/agents/${agentId}`);
    };

    return (
        <div className="flex-1 h-full bg-[var(--color-bg-app)] overflow-y-auto pb-20 md:pb-0">
            {/* Header */}
            <div className="bg-white/80 backdrop-blur-md sticky top-0 z-10 px-6 py-4 flex items-center justify-between border-b border-[var(--color-border-light)]">
                <div>
                    <h1 className="text-xl font-bold text-[var(--color-text-main)] flex items-center gap-2">
                        <Bot className="text-[var(--color-primary)]" />
                        {t('ai_assistants') || 'AI Assistants'}
                    </h1>
                    <p className="text-xs text-[var(--color-text-muted)] mt-1">
                        {t('ai_assistants_desc') || 'Specialized agents for coding, writing, and research'}
                    </p>
                </div>
            </div>

            {/* Search */}
            <div className="px-6 py-4">
                <div className="relative group">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[var(--color-text-muted)] group-focus-within:text-[var(--color-primary)] transition-colors" size={18} />
                    <input
                        type="text"
                        placeholder={t('search_agents') || 'Search agents...'}
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full bg-white border border-[var(--color-border)] rounded-xl py-3 pl-10 pr-4 shadow-sm focus:outline-none focus:border-[var(--color-primary)] focus:shadow-md transition-all"
                    />
                </div>
            </div>

            {/* Agents Grid */}
            <div className="px-6 pb-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {filteredAgents.map((agent, index) => {
                    const displayName = language === 'zh' ? (agent.name_zh || agent.name) : agent.name;
                    const desc = language === 'zh' ? (agent.personality_zh || agent.personality) : agent.personality;

                    return (
                        <div
                            key={agent.id}
                            className="bg-white rounded-2xl p-5 border border-[var(--color-border-light)] shadow-sm hover:shadow-float hover:-translate-y-1 transition-all duration-300 group cursor-pointer flex flex-col h-full"
                            onClick={() => handleChat(agent.id)}
                            style={{ animation: `fadeIn 0.5s ease-out ${index * 50}ms backwards` }}
                        >
                            <div className="flex items-start justify-between mb-4">
                                <div className={cn(
                                    "w-16 h-16 rounded-2xl overflow-hidden shadow-sm group-hover:scale-105 transition-transform flex items-center justify-center bg-gray-50",
                                    agent.color?.split(' ')[0]
                                )}>
                                    <img
                                        src={agent.avatar}
                                        alt={displayName}
                                        className="w-full h-full object-cover"
                                        onError={(e) => {
                                            e.target.style.display = 'none';
                                            e.target.parentElement.innerHTML = '<span class="text-2xl">馃</span>';
                                        }}
                                    />
                                </div>
                                <div className="p-2 bg-[var(--color-bg-app)] rounded-full text-[var(--color-primary)] group-hover:bg-[var(--color-primary)] group-hover:text-white transition-colors shadow-sm">
                                    <MessageSquare size={18} />
                                </div>
                            </div>

                            <h3 className="font-bold text-lg text-[var(--color-text-main)] mb-1">{displayName}</h3>
                            <p className="text-sm text-[var(--color-text-secondary)] line-clamp-3 mb-4 flex-grow">
                                {desc}
                            </p>

                            <div className="mt-auto flex flex-wrap gap-2">
                                {agent.skills?.slice(0, 3).map((skill, i) => (
                                    <span key={i} className="text-[10px] px-2 py-1 rounded-md bg-gray-100 text-gray-600 font-medium uppercase tracking-wider">
                                        {skill.replace(/-/g, ' ')}
                                    </span>
                                ))}
                            </div>
                        </div>
                    );
                })}


                {filteredAgents.length === 0 && (
                    <div className="col-span-full py-12 flex flex-col items-center justify-center text-[var(--color-text-muted)]">
                        <Bot size={48} className="mb-4 opacity-20" />
                        <p>{t('no_agents_found') || 'No agents found matching your search.'}</p>
                    </div>
                )}
            </div>
        </div>
    );
}

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Star, Users, ChevronRight, Settings, Sparkles, X } from 'lucide-react';
import { useChat } from '../features/chat/context/ChatContext';
import { useFriend } from '../context/FriendContext';
import { useLanguage } from '../context/LanguageContext';
import FriendDetail from '../components/FriendDetail';
import { cn } from '../utils/cn';

export default function FriendsPage() {
    const navigate = useNavigate();
    const { personas } = useChat();
    const { groups, getFriendMeta, getDisplayName, getStarredFriends, getFriendsInGroup, getUngroupedFriends } = useFriend();
    const { t, language } = useLanguage();

    const [searchTerm, setSearchTerm] = useState('');
    const [searchFocused, setSearchFocused] = useState(false);
    const [activeFilter, setActiveFilter] = useState('all'); // 'all', 'starred', or group id
    const [selectedFriend, setSelectedFriend] = useState(null);

    // Filter friends based on search and active filter
    const getFilteredFriends = () => {
        let filtered = personas;

        // Apply search filter
        if (searchTerm) {
            filtered = filtered.filter(p => {
                const displayName = getDisplayName(p, language);
                const originalName = language === 'zh' ? (p.name_zh || p.name) : p.name;
                return displayName.toLowerCase().includes(searchTerm.toLowerCase()) ||
                    originalName.toLowerCase().includes(searchTerm.toLowerCase());
            });
        }

        // Apply category filter
        if (activeFilter === 'starred') {
            filtered = getStarredFriends(filtered);
        } else if (activeFilter !== 'all') {
            filtered = getFriendsInGroup(activeFilter, filtered);
        }

        // Sort: starred first, then alphabetically
        return filtered.sort((a, b) => {
            const aMeta = getFriendMeta(a.id);
            const bMeta = getFriendMeta(b.id);
            if (aMeta.starred && !bMeta.starred) return -1;
            if (!aMeta.starred && bMeta.starred) return 1;
            return getDisplayName(a, language).localeCompare(getDisplayName(b, language));
        });
    };

    const filteredFriends = getFilteredFriends();
    const starredCount = getStarredFriends(personas).length;

    return (
        <div className="flex-1 h-full bg-[var(--color-bg-app)] overflow-hidden flex flex-col pb-16 md:pb-0">
            {/* Header - Premium with aurora accent */}
            <div className="glass-strong px-4 py-4 flex items-center justify-between border-b border-[var(--color-border-light)]
                sticky top-0 z-20 animate-fade-slide-down">
                {/* Aurora accent */}
                <div className="absolute bottom-0 left-0 right-0 h-[1px] opacity-40"
                    style={{ background: 'var(--gradient-aurora)' }} />
                
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl flex items-center justify-center shadow-sm"
                        style={{ background: 'var(--gradient-aurora-soft)' }}>
                        <Users size={20} className="text-[var(--color-primary)]" />
                    </div>
                    <div>
                        <h1 className="text-lg font-bold text-[var(--color-text-main)] font-display">
                            {t('friends') || 'Friends'}
                        </h1>
                        <p className="text-xs text-[var(--color-text-muted)]">
                            {personas.length} {language === 'zh' ? '浣岮I浼欎即' : 'AI companions'}
                        </p>
                    </div>
                </div>
                <button
                    onClick={() => navigate('/friends/groups')}
                    className="p-2.5 rounded-xl text-[var(--color-text-muted)] hover:text-[var(--color-primary)]
                        hover:bg-[var(--color-bg-hover)] transition-all duration-200"
                >
                    <Settings size={22} />
                </button>
            </div>

            {/* Search - Premium */}
            <div className="p-4 bg-[var(--color-bg-app)]">
                <div className={cn(
                    "relative transition-all duration-300",
                    searchFocused && "scale-[1.02]"
                )}>
                    <Search className={cn(
                        "absolute left-4 top-1/2 -translate-y-1/2 transition-all duration-300",
                        searchFocused ? "text-[var(--color-primary)] scale-110" : "text-[var(--color-text-muted)]"
                    )} size={18} />
                    <input
                        type="text"
                        placeholder={t('search') || 'Search'}
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        onFocus={() => setSearchFocused(true)}
                        onBlur={() => setSearchFocused(false)}
                        className={cn(
                            "w-full bg-white border-2 rounded-xl py-3 pl-11 pr-10 text-sm",
                            "text-[var(--color-text-main)] placeholder:text-[var(--color-text-muted)]",
                            "focus:outline-none transition-all duration-300 shadow-sm",
                            searchFocused
                                ? "border-[var(--color-primary)] shadow-lg"
                                : "border-transparent hover:border-[var(--color-border)]"
                        )}
                    />
                    {searchTerm && (
                        <button
                            onClick={() => setSearchTerm('')}
                            className="absolute right-3 top-1/2 -translate-y-1/2 p-1.5 rounded-full
                                hover:bg-[var(--color-bg-hover)] text-[var(--color-text-muted)] transition-colors"
                        >
                            <X size={14} />
                        </button>
                    )}
                </div>
            </div>

            {/* Filter Tabs - Premium Pills */}
            <div className="px-4 pb-3 flex gap-2 overflow-x-auto scrollbar-hide">
                <FilterTab
                    active={activeFilter === 'all'}
                    onClick={() => setActiveFilter('all')}
                    label={t('all_friends') || 'All'}
                    count={personas.length}
                />
                <FilterTab
                    active={activeFilter === 'starred'}
                    onClick={() => setActiveFilter('starred')}
                    label={<><Star size={14} className="inline mr-1" />{t('starred_friends') || 'Starred'}</>}
                    count={starredCount}
                    highlight
                />
                {groups.map(group => (
                    <FilterTab
                        key={group.id}
                        active={activeFilter === group.id}
                        onClick={() => setActiveFilter(group.id)}
                        label={<><span className="mr-1">{group.icon}</span>{language === 'zh' ? group.name : group.name_en}</>}
                        count={getFriendsInGroup(group.id, personas).length}
                        color={group.color}
                    />
                ))}
            </div>

            {/* Friend List - Card style */}
            <div className="flex-1 overflow-y-auto px-4 pb-4">
                {filteredFriends.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-16 animate-fade-slide-up">
                        <div className="w-24 h-24 rounded-full flex items-center justify-center mb-6 animate-float"
                            style={{ background: 'var(--gradient-aurora-soft)' }}>
                            <Users size={40} className="text-[var(--color-primary)] opacity-80" />
                        </div>
                        <p className="text-[var(--color-text-muted)] text-center">
                            {t('no_friends_found') || 'No friends found'}
                        </p>
                    </div>
                ) : (
                    <div className="space-y-2">
                        {filteredFriends.map((friend, index) => {
                            const meta = getFriendMeta(friend.id);
                            const displayName = getDisplayName(friend, language);
                            const originalName = language === 'zh' ? (friend.name_zh || friend.name) : friend.name;
                            const friendGroup = groups.find(g => g.id === meta.groupId);

                            return (
                                <div
                                    key={friend.id}
                                    onClick={() => setSelectedFriend(friend)}
                                    className="flex items-center px-4 py-3.5 bg-white rounded-2xl shadow-sm
                                        border border-transparent hover:border-[var(--color-border-aurora)]
                                        hover:shadow-md active:scale-[0.99] cursor-pointer
                                        transition-all duration-300 group animate-fade-slide-up"
                                    style={{ animationDelay: `${index * 30}ms` }}
                                >
                                    {/* Avatar with hover effect */}
                                    <div className="relative w-12 h-12 rounded-xl overflow-hidden flex-shrink-0 mr-4
                                        shadow-sm group-hover:shadow-md group-hover:scale-105 transition-all duration-300">
                                        <img src={friend.avatar} alt={displayName} className="w-full h-full object-cover" />
                                        {/* Online indicator */}
                                        <div className="absolute bottom-0 right-0 w-3.5 h-3.5 bg-[var(--color-success)]
                                            rounded-full border-2 border-white shadow-sm" />
                                    </div>

                                    {/* Name and Info */}
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2">
                                            <span className="text-[15px] font-semibold text-[var(--color-text-main)] truncate
                                                group-hover:text-[var(--color-primary)] transition-colors">
                                                {displayName}
                                            </span>
                                            {meta.starred && (
                                                <Star size={14} className="text-[var(--color-accent-gold)] fill-current flex-shrink-0" />
                                            )}
                                        </div>
                                        <div className="flex items-center gap-2 mt-1">
                                            {meta.remark && displayName !== originalName && (
                                                <span className="text-[12px] text-[var(--color-text-muted)]">
                                                    ({originalName})
                                                </span>
                                            )}
                                            {friendGroup && (
                                                <span
                                                    className="text-[11px] px-2 py-0.5 rounded-full font-medium"
                                                    style={{ backgroundColor: friendGroup.color + '15', color: friendGroup.color }}
                                                >
                                                    {friendGroup.icon} {language === 'zh' ? friendGroup.name : friendGroup.name_en}
                                                </span>
                                            )}
                                        </div>
                                    </div>

                                    <ChevronRight size={20} className="text-[var(--color-text-light)] flex-shrink-0
                                        group-hover:text-[var(--color-primary)] group-hover:translate-x-1 transition-all" />
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>

            {/* Friend Detail Modal */}
            {selectedFriend && (
                <FriendDetail
                    friend={selectedFriend}
                    onClose={() => setSelectedFriend(null)}
                />
            )}
        </div>
    );
}

function FilterTab({ active, onClick, label, count, highlight, color }) {
    return (
        <button
            onClick={onClick}
            className={cn(
                "px-4 py-2 rounded-xl text-[13px] font-semibold whitespace-nowrap flex items-center gap-1.5",
                "transition-all duration-300 shadow-sm border",
                active
                    ? "text-white shadow-md border-transparent animate-aurora"
                    : highlight
                        ? "bg-amber-50 text-amber-700 border-amber-100 hover:shadow-md"
                        : color
                            ? "border-transparent hover:shadow-md"
                            : "bg-white text-[var(--color-text-muted)] border-[var(--color-border-light)] hover:border-[var(--color-border)] hover:shadow-md"
            )}
            style={active 
                ? { background: 'var(--gradient-aurora)', backgroundSize: '200% 200%' }
                : !highlight && color 
                    ? { backgroundColor: color + '12', color: color, borderColor: color + '30' } 
                    : {}
            }
        >
            {label}
            {count !== undefined && (
                <span className={cn(
                    "text-[11px] px-1.5 py-0.5 rounded-full font-medium",
                    active ? "bg-white/25 text-white" : "bg-black/5"
                )}>
                    {count}
                </span>
            )}
        </button>
    );
}

