import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ChevronLeft, Camera, User, Edit2 } from 'lucide-react';
import { useLanguage } from '../context/LanguageContext';
import { useUser } from '../context/UserContext';
import AvatarSelector from '../components/AvatarSelector';
import { cn } from '../utils/cn';

export default function ProfileEditor() {
    const navigate = useNavigate();
    const { t, language } = useLanguage();
    const { userProfile, updateNickname, updateAvatar, updateSignature, getDisplayName } = useUser();

    const [nickname, setNickname] = useState('');
    const [signature, setSignature] = useState('');
    const [showAvatarSelector, setShowAvatarSelector] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        setNickname(userProfile.nickname || '');
        setSignature(userProfile.signature || '');
    }, [userProfile]);

    const handleSave = () => {
        setIsSaving(true);
        updateNickname(nickname);
        updateSignature(signature);

        setTimeout(() => {
            setIsSaving(false);
            navigate(-1);
        }, 300);
    };

    const handleAvatarSelect = (avatar) => {
        updateAvatar(avatar);
    };

    return (
        <div className="flex-1 h-full bg-[var(--color-bg-app)] overflow-y-auto">
            {/* Header */}
            <div className="bg-white sticky top-0 z-10 flex items-center justify-between px-4 py-3 border-b border-[var(--color-border)]">
                <button onClick={() => navigate(-1)} className="flex items-center text-[var(--color-primary)]">
                    <ChevronLeft size={24} />
                    <span>{t('cancel') || 'Cancel'}</span>
                </button>
                <h1 className="font-medium text-[17px]">{t('edit_profile') || 'Edit Profile'}</h1>
                <button
                    onClick={handleSave}
                    disabled={isSaving}
                    className={cn(
                        "text-[var(--color-primary)] font-medium",
                        isSaving && "opacity-50"
                    )}
                >
                    {t('save') || 'Save'}
                </button>
            </div>

            {/* Avatar Section */}
            <div className="bg-white mt-2 py-6">
                <div className="flex flex-col items-center">
                    <button
                        onClick={() => setShowAvatarSelector(true)}
                        className="relative group"
                    >
                        <div className="w-24 h-24 rounded-full overflow-hidden border-4 border-white shadow-lg">
                            {userProfile.avatar ? (
                                <img
                                    src={userProfile.avatar}
                                    alt="Avatar"
                                    className="w-full h-full object-cover"
                                />
                            ) : (
                                <div className="w-full h-full bg-[var(--color-primary)] flex items-center justify-center text-white text-3xl font-bold">
                                    {getDisplayName(language).charAt(0).toUpperCase()}
                                </div>
                            )}
                        </div>
                        <div className="absolute inset-0 rounded-full bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                            <Camera size={28} className="text-white" />
                        </div>
                    </button>
                    <span className="mt-2 text-[var(--color-text-muted)] text-sm">
                        {t('avatar') || 'Avatar'}
                    </span>
                </div>
            </div>

            {/* Nickname Section */}
            <div className="bg-white mt-2">
                <div className="px-4 py-3 border-b border-[var(--color-border-light)]">
                    <label className="block text-[var(--color-text-muted)] text-sm mb-2">
                        {t('nickname') || 'Nickname'}
                    </label>
                    <div className="flex items-center gap-3">
                        <User size={20} className="text-[var(--color-text-muted)]" />
                        <input
                            type="text"
                            value={nickname}
                            onChange={(e) => setNickname(e.target.value)}
                            onBlur={(e) => setNickname(e.target.value)}
                            onInput={(e) => setNickname(e.target.value)}
                            placeholder={t('nickname_placeholder') || 'Enter your nickname'}
                            maxLength={20}
                            className="flex-1 py-2 text-[16px] bg-transparent outline-none placeholder:text-[var(--color-text-light)]"
                        />
                        <span className="text-[var(--color-text-light)] text-sm">
                            {nickname.length}/20
                        </span>
                    </div>
                </div>
            </div>

            {/* Signature Section */}
            <div className="bg-white mt-2">
                <div className="px-4 py-3">
                    <label className="block text-[var(--color-text-muted)] text-sm mb-2">
                        {t('signature') || 'Signature / Status'}
                    </label>
                    <div className="flex items-start gap-3">
                        <Edit2 size={20} className="text-[var(--color-text-muted)] mt-2" />
                        <div className="flex-1">
                            <textarea
                                value={signature}
                                onChange={(e) => setSignature(e.target.value)}
                                placeholder={t('signature_placeholder') || 'Say something about yourself...'}
                                maxLength={100}
                                rows={3}
                                className="w-full py-2 text-[16px] bg-transparent outline-none resize-none placeholder:text-[var(--color-text-light)]"
                            />
                            <div className="text-right text-[var(--color-text-light)] text-sm">
                                {signature.length}/100
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* User ID (Read Only) */}
            <div className="bg-white mt-2">
                <div className="px-4 py-3 flex items-center justify-between">
                    <span className="text-[var(--color-text-muted)]">{t('user_id') || 'User ID'}</span>
                    <span className="text-[var(--color-text-main)]">{userProfile.id}</span>
                </div>
            </div>

            {/* Avatar Selector Modal */}
            <AvatarSelector
                isOpen={showAvatarSelector}
                onClose={() => setShowAvatarSelector(false)}
                currentAvatar={userProfile.avatar}
                onSelect={handleAvatarSelect}
            />
        </div>
    );
}

/**
 * Advanced Translation Service - Implements YAML-based reflective translation
 * Based on "Immersive Translate" architecture patterns
 * 
 * Core Features:
 * - Two-step reflective workflow (literal 鈫?polished)
 * - Domain-adaptive expert prompts
 * - YAML structured I/O for reliable parsing
 * - Dynamic terminology injection
 */

import { callAI } from '../../features/chat/services/chatService';
import { buildExpertPrompt } from '../../data/translationExperts';
import { buildTermsPrompt, findMatchingTerms, getCombinedGlossary } from '../../data/glossary';

// ========== Domain Detection ==========

/**
 * Detect content domain based on text patterns
 * @param {string} text - Source text to analyze
 * @returns {'technical' | 'literary' | 'general'} Detected domain
 */
export function detectDomain(text) {
    if (!text || typeof text !== 'string') return 'general';

    const textLower = text.toLowerCase();

    // Technical indicators
    const technicalPatterns = [
        /```[\s\S]*?```/,                    // Code blocks
        /`[^`]+`/,                            // Inline code
        /\b(function|const|let|var|import|export|class|interface)\b/,
        /\b(API|SDK|HTTP|JSON|XML|CSS|HTML|DOM|URL)\b/i,
        /\b(npm|yarn|pip|git|docker|kubernetes)\b/i,
        /\b(useState|useEffect|onClick|props|component)\b/,
        /\b(async|await|promise|callback|observable)\b/i,
        /\b(repository|commit|branch|merge|deploy)\b/i,
        /\[\w+\]\([^)]+\)/,                   // Markdown links
        /<\/?[a-z][\s\S]*?>/i,               // HTML tags
    ];

    // Literary indicators
    const literaryPatterns = [
        /"[^"]{20,}"/,                        // Long quoted dialogue
        /\b(whispered|murmured|exclaimed|sighed)\b/i,
        /\b(heart|soul|tears|love|fear|hope|dream)\b/i,
        /\b(chapter|story|novel|poem|verse)\b/i,
        /\b(once upon|happily ever|the end)\b/i,
        /[.!?]["']\s/,                        // Dialogue punctuation
        /鈥攟鈥搢\.{3}/,                          // Literary punctuation (em dash, ellipsis)
    ];

    // Count matches
    let technicalScore = 0;
    let literaryScore = 0;

    technicalPatterns.forEach(pattern => {
        if (pattern.test(text)) technicalScore++;
    });

    literaryPatterns.forEach(pattern => {
        if (pattern.test(text)) literaryScore++;
    });

    // Threshold-based decision
    if (technicalScore >= 3) return 'technical';
    if (literaryScore >= 3) return 'literary';
    if (technicalScore > literaryScore) return 'technical';
    if (literaryScore > technicalScore) return 'literary';

    return 'general';
}

// ========== YAML Protocol ==========

/**
 * Build YAML request object for translation
 * @param {string} text - Source text
 * @param {Object} options - Additional options
 * @returns {string} YAML-formatted request
 */
function buildYAMLRequest(text, options = {}) {
    const id = options.id || '0';
    const context = options.context || '';

    // Escape text for YAML (handle quotes and special chars)
    const escapedText = text
        .replace(/\\/g, '\\\\')
        .replace(/"/g, '\\"')
        .replace(/\n/g, '\\n');

    let yaml = `- id: "${id}"\n  source: "${escapedText}"`;

    if (context) {
        yaml += `\n  context: "${context}"`;
    }

    return yaml;
}

/**
 * Parse YAML response from LLM
 * Robust parsing that handles common LLM output variations
 * @param {string} response - Raw LLM response
 * @returns {Object} Parsed result with step1 and step2
 */
function parseYAMLResponse(response) {
    if (!response) {
        throw new Error('Empty response from translation API');
    }

    // Try to extract YAML block if wrapped in code fence
    let yamlContent = response;
    const yamlMatch = response.match(/```ya?ml\s*([\s\S]*?)```/i);
    if (yamlMatch) {
        yamlContent = yamlMatch[1].trim();
    }

    // Try simple regex parsing for our expected format
    const step1Match = yamlContent.match(/step1:\s*["']?([\s\S]*?)["']?\s*(?=step2:|$)/i);
    const step2Match = yamlContent.match(/step2:\s*["']?([\s\S]*?)["']?\s*(?=$|\n-\s)/i);

    if (step1Match && step2Match) {
        return {
            step1: cleanYAMLValue(step1Match[1]),
            step2: cleanYAMLValue(step2Match[1])
        };
    }

    // Fallback: try to find any translation-like content
    // Look for Chinese characters as indication of translation
    const chineseMatch = response.match(/[\u4e00-\u9fa5]+[^]*?[\u4e00-\u9fa5]+/);
    if (chineseMatch) {
        console.warn('[TranslationService] YAML parsing failed, using fallback extraction');
        return {
            step1: chineseMatch[0],
            step2: chineseMatch[0]
        };
    }

    // Last resort: return the whole response
    console.warn('[TranslationService] Could not parse YAML response, returning raw');
    return {
        step1: response,
        step2: response
    };
}

/**
 * Clean up YAML value (remove quotes, unescape, trim)
 */
function cleanYAMLValue(value) {
    if (!value) return '';

    return value
        .replace(/^["']+|["']+$/g, '')  // Remove surrounding quotes
        .replace(/\\n/g, '\n')           // Unescape newlines
        .replace(/\\"/g, '"')            // Unescape quotes
        .replace(/\\'/g, "'")
        .trim();
}

// ========== Main Translation Function ==========

/**
 * Two-step reflective translation workflow
 * @param {string} text - Source text to translate
 * @param {Object} options - Translation options
 * @param {string} options.sourceLang - Source language (auto-detected if not provided)
 * @param {string} options.targetLang - Target language (default: 'Chinese')
 * @param {string} options.domain - Content domain ('technical', 'literary', 'general', 'bilingual')
 * @param {Array} options.glossary - Custom term mappings [{source, target}]
 * @param {string} options.context - Optional context (page title, summary)
 * @param {boolean} options.fastMode - If true, use single-step for simple texts
 * @returns {Promise<{step1: string, step2: string, domain: string}>}
 */
export async function translateWithReflection(text, options = {}) {
    if (!text || typeof text !== 'string') {
        throw new Error('Invalid text input for translation');
    }

    const targetLang = options.targetLang || 'Chinese';

    // Step 1: Detect domain if not specified
    const domain = options.domain || detectDomain(text);
    console.log(`[TranslationService] Detected domain: ${domain}`);

    // Step 2: Get matching terms from glossary
    const glossaryTerms = options.glossary || findMatchingTerms(text, domain, targetLang);
    const termsPrompt = buildTermsPrompt(glossaryTerms);
    console.log(`[TranslationService] Found ${glossaryTerms.length} glossary terms`);

    // Step 3: Build expert system prompt
    const systemPrompt = buildExpertPrompt(domain, {
        targetLang,
        sourceLang: options.sourceLang || 'English',
        termsPrompt
    });

    // Step 4: Build YAML request
    const yamlRequest = buildYAMLRequest(text, {
        context: options.context
    });

    // Step 5: Construct user message
    const userMessage = `Please translate the following text according to your workflow:

${yamlRequest}

Remember: 
1. First create step1 (literal translation)
2. Then create step2 (polished translation)
3. Output in the YAML format specified`;

    // Step 6: Call LLM
    console.log('[TranslationService] Calling LLM for translation...');
    const response = await callAI(
        [{ role: 'user', content: userMessage }],
        {
            systemPrompt,
            maxTokens: 2000,
            temperature: 0.3,  // Lower temperature for more consistent translation
            agentId: 'muse-translation'
        }
    );

    if (!response) {
        throw new Error('Translation API returned no response');
    }

    // Step 7: Parse YAML response
    const parsed = parseYAMLResponse(response);

    return {
        ...parsed,
        domain,
        rawResponse: response  // For debugging
    };
}

/**
 * Simple single-step translation (fast mode)
 * @param {string} text - Source text
 * @param {string} targetLang - Target language
 * @returns {Promise<string>} Translated text
 */
export async function translateSimple(text, targetLang = 'Chinese') {
    const systemPrompt = `You are a professional ${targetLang} translator. 
Translate the following text accurately and naturally. 
Return ONLY the translation, no explanations.`;

    const response = await callAI(
        [{ role: 'user', content: text }],
        {
            systemPrompt,
            maxTokens: 1000,
            temperature: 0.3,
            agentId: 'muse-translation-fast'
        }
    );

    return response || text;
}

/**
 * Batch translation for multiple paragraphs
 * @param {Array<string>} texts - Array of text segments
 * @param {Object} options - Translation options
 * @returns {Promise<Array>} Array of translation results
 */
export async function translateBatch(texts, options = {}) {
    // For now, translate sequentially
    // TODO: Implement parallel translation with shared context
    const results = [];

    for (let i = 0; i < texts.length; i++) {
        const result = await translateWithReflection(texts[i], {
            ...options,
            id: String(i)
        });
        results.push(result);
    }

    return results;
}

// ========== Utility Functions ==========

/**
 * Get language name for display
 */
export function getLanguageName(code) {
    const languages = {
        'zh': 'Chinese',
        'en': 'English',
        'ja': 'Japanese',
        'ko': 'Korean',
        'es': 'Spanish',
        'fr': 'French',
        'de': 'German',
        'ru': 'Russian'
    };
    return languages[code] || code;
}

/**
 * Detect source language (simple heuristic)
 */
export function detectSourceLanguage(text) {
    if (!text) return 'en';

    // Check for Chinese characters
    if (/[\u4e00-\u9fa5]/.test(text)) return 'zh';

    // Check for Japanese (hiragana/katakana)
    if (/[\u3040-\u309f\u30a0-\u30ff]/.test(text)) return 'ja';

    // Check for Korean
    if (/[\uac00-\ud7af]/.test(text)) return 'ko';

    // Default to English
    return 'en';
}

export default {
    translateWithReflection,
    translateSimple,
    translateBatch,
    detectDomain,
    getLanguageName,
    detectSourceLanguage
};

/**
 * Perplexity Sonar API Service
 * 
 * A dedicated client for Perplexity's Sonar models with:
 * - Structured search_results parsing (metadata, citations, snippets)
 * - Domain filtering for academic/news/tech sources
 * - Recency filtering (hour/day/week/month/year)
 * - Multi-hop search strategy for deep research
 * - Citation index mapping system
 * 
 * Based on the Perplexity Sonar API Technical Architecture Report (2025)
 * Uses centralized APIClient for HTTP requests.
 */

import { getAIClient, getAIConfiguration, SONAR_MODELS } from './api/aiClient';

// Re-export SONAR_MODELS for backward compatibility
export { SONAR_MODELS };

/**
 * Domain Filter Presets
 * For search_domain_filter API parameter
 */
export const DOMAIN_PRESETS = {
    ACADEMIC: ['arxiv.org', 'nature.com', 'sciencedirect.com', 'ieee.org', 'scholar.google.com', '.edu'],
    NEWS: ['reuters.com', 'bbc.com', 'nytimes.com', 'apnews.com', 'theguardian.com'],
    TECH: ['github.com', 'stackoverflow.com', 'medium.com', 'dev.to', 'hackernews.com'],
    GENERAL: [] // No filter - search all domains
};

/**
 * Recency Filter Options
 * For search_recency_filter API parameter
 */
export const RECENCY_OPTIONS = {
    HOUR: 'hour',
    DAY: 'day',
    WEEK: 'week',
    MONTH: 'month',
    YEAR: 'year'
};

// ========== Core API Functions ==========

/**
 * Execute a grounded search using Perplexity Sonar
 * 
 * @param {string} query - Search query
 * @param {Object} options - Configuration options
 * @param {string} options.model - Sonar model to use (default: sonar-pro)
 * @param {string[]} options.domainFilter - Array of domains to restrict search
 * @param {string} options.recency - Recency filter (hour/day/week/month/year)
 * @param {number} options.maxTokens - Max response tokens (default: 1024)
 * @param {number} options.temperature - Response temperature (default: 0.2 for factual)
 * @param {string} options.systemPrompt - Custom system prompt
 * @param {boolean} options.returnCitations - Include search_results (default: true)
 * @returns {Promise<SonarSearchResult>} Structured search result
 * 
 * @typedef {Object} SonarSearchResult
 * @property {string} answer - The generated answer with [x] citation markers
 * @property {SearchResult[]} searchResults - Array of source metadata
 * @property {string[]} citations - Legacy URL-only citations (fallback)
 * @property {string} model - Model used for the request
 * @property {number} tokensUsed - Approximate tokens consumed
 * 
 * @typedef {Object} SearchResult
 * @property {number} index - Citation index (0-based, maps to [1] in text)
 * @property {string} title - Page title
 * @property {string} url - Source URL
 * @property {string} snippet - Relevant excerpt from the page
 * @property {string} date - Publication/last updated date (if available)
 */
export async function sonarSearch(query, options = {}) {
    const aiClient = getAIClient();
    const config = getAIConfiguration();

    if (!config.apiKey) {
        throw new Error('Perplexity API key not configured. Set VITE_AI_API_KEY in .env');
    }

    const {
        model = SONAR_MODELS.PRO,
        domainFilter = [],
        recency = null,
        maxTokens = 1024,
        temperature = 0.2,
        systemPrompt = null,
        returnCitations = true
    } = options;

    // Build messages array
    const messages = [];

    if (systemPrompt) {
        messages.push({ role: 'system', content: systemPrompt });
    }

    messages.push({ role: 'user', content: query });

    // Build request body with Perplexity-specific parameters
    const requestBody = {
        model,
        messages,
        temperature,
        max_tokens: maxTokens,
        // Perplexity-specific parameters
        return_citations: returnCitations,
        return_images: false,
        return_related_questions: false
    };

    // Add domain filter if specified
    if (domainFilter && domainFilter.length > 0) {
        requestBody.search_domain_filter = domainFilter;
    }

    // Add recency filter if specified
    if (recency && Object.values(RECENCY_OPTIONS).includes(recency)) {
        requestBody.search_recency_filter = recency;
    }

    console.log('[PerplexityService] Sending request:', {
        model,
        query: query.substring(0, 50) + '...',
        domainFilter,
        recency
    });

    try {
        const response = await aiClient.post('/chat/completions', requestBody);

        const data = await response.json();

        if (data.error) {
            console.error('[PerplexityService] API Error:', data.error);
            throw new Error(data.error.message || 'Perplexity API error');
        }

        // Parse the response
        return parsePerplexityResponse(data, model);

    } catch (error) {
        console.error('[PerplexityService] Request failed:', error);
        throw error;
    }
}

/**
 * Execute deep multi-hop research
 * Performs multiple search iterations to build comprehensive understanding
 * 
 * @param {string} query - Initial research question
 * @param {Object} options - Search options (passed to sonarSearch)
 * @param {number} options.depth - Number of search hops (default: 2, max: 3)
 * @returns {Promise<DeepResearchResult>}
 * 
 * @typedef {Object} DeepResearchResult
 * @property {string} synthesis - Synthesized answer combining all hops
 * @property {SearchResult[]} allSources - Deduplicated sources from all hops
 * @property {string[]} searchQueries - Queries used in each hop
 */
export async function deepResearch(query, options = {}) {
    const { depth = 2, ...searchOptions } = options;
    const maxDepth = Math.min(depth, 3); // Cap at 3 hops to avoid runaway costs

    const allSources = [];
    const searchQueries = [query];
    let currentContext = '';
    let synthesis = '';

    console.log(`[PerplexityService] Starting deep research with ${maxDepth} hops`);

    for (let hop = 0; hop < maxDepth; hop++) {
        const currentQuery = hop === 0
            ? query
            : `Given this context: "${currentContext.substring(0, 500)}..." 
               What additional information is needed to fully answer: "${query}"?
               Focus on gaps, contradictions, or unexplored aspects.`;

        if (hop > 0) searchQueries.push(currentQuery);

        try {
            const result = await sonarSearch(currentQuery, {
                ...searchOptions,
                model: hop === 0 ? SONAR_MODELS.PRO : SONAR_MODELS.LARGE,
                maxTokens: 800
            });

            // Accumulate sources (dedupe by URL)
            result.searchResults.forEach(source => {
                if (!allSources.some(s => s.url === source.url)) {
                    allSources.push({
                        ...source,
                        index: allSources.length,
                        hopNumber: hop + 1
                    });
                }
            });

            currentContext += '\n' + result.answer;
            synthesis = result.answer; // Latest answer is the synthesis

        } catch (error) {
            console.warn(`[PerplexityService] Hop ${hop + 1} failed:`, error.message);
            break; // Stop on error, return what we have
        }
    }

    // Re-index citations in synthesis to match allSources
    const reindexedSynthesis = reindexCitations(synthesis, allSources);

    return {
        synthesis: reindexedSynthesis,
        allSources,
        searchQueries,
        hopsCompleted: searchQueries.length
    };
}

/**
 * Fact-check a specific claim
 * Uses reasoning model for logical analysis
 * 
 * @param {string} claim - The claim to verify
 * @param {Object} options - Search options
 * @returns {Promise<FactCheckResult>}
 * 
 * @typedef {Object} FactCheckResult
 * @property {string} verdict - 'verified' | 'disputed' | 'unverifiable'
 * @property {string} confidence - 'high' | 'medium' | 'low'
 * @property {string} explanation - Reasoning for the verdict
 * @property {SearchResult[]} sources - Supporting/refuting sources
 */
export async function factCheck(claim, options = {}) {
    const systemPrompt = `You are a rigorous fact-checker. Analyze the following claim:

## Your Task:
1. Search for evidence supporting OR refuting this claim
2. Evaluate source reliability and consensus
3. Provide a clear verdict

## Output Format (JSON):
{
    "verdict": "verified" | "disputed" | "unverifiable",
    "confidence": "high" | "medium" | "low",
    "explanation": "Brief explanation of your reasoning",
    "key_evidence": ["Evidence point 1", "Evidence point 2"]
}

## Verdict Criteria:
- verified: Multiple reliable sources confirm, no credible disputes
- disputed: Sources conflict or claim is partially true
- unverifiable: Insufficient evidence or contradictory data

Do NOT include your own opinions. Base verdict ONLY on search results.`;

    try {
        const result = await sonarSearch(claim, {
            ...options,
            model: SONAR_MODELS.REASONING,
            systemPrompt,
            temperature: 0.1,
            maxTokens: 600
        });

        // Try to parse JSON from response
        const jsonMatch = result.answer.match(/\{[\s\S]*\}/);
        let parsed = {
            verdict: 'unverifiable',
            confidence: 'low',
            explanation: result.answer
        };

        if (jsonMatch) {
            try {
                parsed = JSON.parse(jsonMatch[0]);
            } catch (e) {
                // JSON parsing failed, use raw answer
            }
        }

        return {
            ...parsed,
            sources: result.searchResults,
            rawAnswer: result.answer
        };

    } catch (error) {
        return {
            verdict: 'unverifiable',
            confidence: 'low',
            explanation: `Fact-check failed: ${error.message}`,
            sources: []
        };
    }
}

// ========== Response Parsing ==========

/**
 * Parse Perplexity API response into structured format
 * Handles both legacy `citations` array and new `search_results` object
 */
function parsePerplexityResponse(data, model) {
    const choice = data.choices?.[0];
    const answer = choice?.message?.content?.trim() || '';

    // Prefer search_results (new format) over citations (legacy)
    let searchResults = [];

    if (data.search_results && Array.isArray(data.search_results)) {
        // New format: Rich metadata
        searchResults = data.search_results.map((result, index) => ({
            index,
            title: result.title || 'Untitled',
            url: result.url || '',
            snippet: result.snippet || result.content || '',
            date: result.date || result.published_date || null
        }));
    } else if (data.citations && Array.isArray(data.citations)) {
        // Legacy format: URL strings only
        searchResults = data.citations.map((url, index) => ({
            index,
            title: extractTitleFromUrl(url),
            url,
            snippet: '',
            date: null
        }));
    }

    // Extract citation indices from the answer text
    const citationIndices = extractCitationIndices(answer);

    return {
        answer,
        searchResults,
        citations: data.citations || searchResults.map(r => r.url),
        citationIndices,
        model,
        tokensUsed: data.usage?.total_tokens || 0,
        id: data.id
    };
}

/**
 * Extract citation indices [1], [2], etc. from text
 */
function extractCitationIndices(text) {
    const matches = text.match(/\[(\d+)\]/g) || [];
    return [...new Set(matches.map(m => parseInt(m.replace(/[\[\]]/g, ''), 10) - 1))];
}

/**
 * Extract a readable title from URL
 */
function extractTitleFromUrl(url) {
    try {
        const urlObj = new URL(url);
        const pathParts = urlObj.pathname.split('/').filter(Boolean);
        if (pathParts.length > 0) {
            return pathParts[pathParts.length - 1]
                .replace(/[-_]/g, ' ')
                .replace(/\.\w+$/, '')
                .split(' ')
                .map(w => w.charAt(0).toUpperCase() + w.slice(1))
                .join(' ');
        }
        return urlObj.hostname;
    } catch {
        return 'Source';
    }
}

/**
 * Re-index citation markers in text to match a new source array
 */
function reindexCitations(text, sources) {
    // This is a simple implementation - in production you'd want
    // to track which sources came from which hop and remap properly
    return text;
}

